          probability: '۰٪ (صفر درصد - رهبر تاریخی و ملی ایران، انسان ۱۰۰٪ واقعی و چهره رسمی بین‌المللی)',
          redFlags: '• 🦁 پرچمدار انقلاب ملی و درفش جاودان شیر و خورشید: چهره محوری همبستگی میهنی، احیای کرامت و غرور ایرانیان و رهبر خیزش ملی با شعار بنیادین «ایران را پس می‌گیریم».\n• 🏛️ تعهد به دموکراسی و رای آزاد ملت: مدافع سرسخت تمامیت ارضی، حاکمیت ملی و برقراری دموکراسی سکولار بر پایه صندوق آزاد رای و اعلامیه جهانی حقوق بشر.\n• 🕊️ پیمان نوین و همبستگی همگانی: تمرکز خستگی‌ناپذیر بر گذار از فرقه تبهکار حاکم بدون سهم‌خواهی شخصی از قدرت، با هدف سپردن تعیین نوع حکومت آینده به اراده آزاد خود مردم ایران.\n• 🌐 دیپلماسی فعال بین‌المللی و بازسازی میهن: ارتباط مقتدرانه با رهبران جهان برای انزوای رژیم جمهوری اسلامی و تدوین برنامه‌های تخصصی نجات و بازسازی اقتصادی ایران (پروژه سیمرغ و MIGA).',
