          verdict: '⚠️ هشدار طیف چپ رادیکال و ضد پادشاهی: شادی صدر از چهره‌های شاخص چپ رادیکال، فمینیسم ضد ملی و مروج فدرالیسم قومی است. این اکانت به هیچ عنوان «روزنامه‌نگار مستقل یا رسانه بی‌طرف» نبوده و در تقابل کامل با جریان پادشاهی‌خواهی و تمامیت ارضی ایران قرار دارد!',
