/**
 * Normalizes Persian/English text for robust name/handle matching
 */
function normalizeEntityText(str) {
  if (!str) return '';
  return str
    .toLowerCase()
    .replace(/[@_#\-\.\s]/g, '')
    .replace(/[ي]/g, 'ی')
    .replace(/[ك]/g, 'ک')
    .replace(/[‌]/g, '')
    .replace(/[غ]/g, 'ق');
}

/**
 * Reads user-pinned custom accounts map from storage
 */
async function getCustomAccountsMap() {
  try {
    const syncData = await chrome.storage.sync.get(['xrayCustomAccounts']).catch(() => ({}));
    const localData = await chrome.storage.local.get(['xrayCustomAccounts']).catch(() => ({}));
    return { ...(localData?.xrayCustomAccounts || {}), ...(syncData?.xrayCustomAccounts || {}) };
  } catch (e) {
    return {};
  }
}

/**
 * Resolves the known political faction of any @handle for Interaction Graph Analysis
 * Returns { faction, label } or null
 */
function resolveHandleFaction(handle, customMap = {}) {
  const normH = normalizeEntityText(handle);
  if (!normH || normH.length < 3) return null;

  // 1. User-pinned accounts
  if (customMap && customMap[normH]) {
    return { faction: customMap[normH].faction, label: customMap[normH].displayName || `@${handle}` };
  }

  // 2. KNOWN_POLITICAL_ACCOUNTS
  for (const item of KNOWN_POLITICAL_ACCOUNTS) {
    for (const h of (item.handles || [])) {
      if (normalizeEntityText(h) === normH) {
        return { faction: item.faction, label: `@${h}` };
      }
    }
  }

  // 3. MEK_HANDLES
  if (typeof MEK_HANDLES !== 'undefined') {
    for (const mh of MEK_HANDLES) {
      const cleanMh = normalizeEntityText(mh);
      if (cleanMh && (normH === cleanMh || (cleanMh.length >= 7 && normH.includes(cleanMh)))) {
        return { faction: 'mek', label: `@${mh}` };
      }
    }
  }

  // 4. KNOWN_AUTHENTIC_ENTITIES (check if they are Pahlavi/Nationalist figures)
  for (const ent of KNOWN_AUTHENTIC_ENTITIES) {
    for (const h of (ent.handles || [])) {
      const cleanEh = normalizeEntityText(h);
      if (cleanEh && normH === cleanEh) {
        if (/پادشاهی|ملی‌گرا|پهلوی/i.test(ent.identity)) {
          return { faction: 'pahlavi', label: ent.names?.[0] || `@${h}` };
        }
        return { faction: 'media', label: ent.names?.[0] || `@${h}` };
      }
    }
  }

  return null;
}

/**
 * Reads persistent X rest_id registry from storage (tracks permanent numeric user IDs & handle changes)
 */
async function getRestIdRegistry() {
  try {
    const localData = await chrome.storage.local.get(['xrayRestIdRegistryV2', 'xrayRestIdRegistry']).catch(() => ({}));
    if (localData?.xrayRestIdRegistry) {
      // Migrate handle history from V1 while stripping any false-positive V1 inferred factions
      const v1 = localData.xrayRestIdRegistry || {};
      const v2 = localData.xrayRestIdRegistryV2 || {};
      for (const [id, item] of Object.entries(v1)) {
        if (!v2[id] && item) {
          v2[id] = {
            restId: item.restId || id,
            currentHandle: item.currentHandle || '',
            displayName: item.displayName || '',
            previousHandles: Array.isArray(item.previousHandles) ? item.previousHandles : [],
            faction: '',
            updatedAt: item.updatedAt || Date.now()
          };
        }
      }
      await chrome.storage.local.set({ xrayRestIdRegistryV2: v2 }).catch(() => {});
      await chrome.storage.local.remove(['xrayRestIdRegistry']).catch(() => {});
      return v2;
    }
    return localData?.xrayRestIdRegistryV2 || {};
  } catch (e) {
    return {};
  }
}

async function saveRestIdRegistry(reg) {
  try {
    const keys = Object.keys(reg || {});
    if (keys.length > 4000) {
      // Trim oldest entries if over 4000
      const sorted = keys.sort((a, b) => (reg[a]?.updatedAt || 0) - (reg[b]?.updatedAt || 0));
      for (let i = 0; i < sorted.length - 3500; i++) {
        delete reg[sorted[i]];
      }
    }
    await chrome.storage.local.set({ xrayRestIdRegistryV2: reg });
  } catch (e) {}
}

/**
 * Reads/writes cached badges of previously scanned accounts
 */
async function getScannedBadgesCache() {
  try {
    const localData = await chrome.storage.local.get(['xrayScannedBadgesCacheV2', 'xrayScannedBadgesCache']).catch(() => ({}));
    if (localData?.xrayScannedBadgesCache) {
      // Clean up legacy V1 cache that had false-positive 'arzeshi' tags on citizen accounts
      chrome.storage.local.remove(['xrayScannedBadgesCache']).catch(() => {});
    }
    return localData?.xrayScannedBadgesCacheV2 || {};
  } catch (e) {
    return {};
  }
}

async function saveScannedBadge(handle, faction, restId = '', displayName = '') {
  const normH = normalizeEntityText(handle);
  if (!normH || !faction) return;
  try {
    const cache = await getScannedBadgesCache();
    cache[normH] = {
      handle: String(handle).startsWith('@') ? handle : `@${handle}`,
      displayName: displayName || handle,
      faction,
      restId: restId || cache[normH]?.restId || '',
      updatedAt: Date.now()
    };
    const keys = Object.keys(cache);
    if (keys.length > 2000) {
      delete cache[keys[0]];
    }
    await chrome.storage.local.set({ xrayScannedBadgesCacheV2: cache });
  } catch (e) {}
}

/**
 * Infers the primary faction key from formatted analysis text for automatic badge caching
 */
function inferFactionFromAnalysisText(analysisText, isMekAlert = false, isFalseFlag = false) {
  if (isMekAlert) return 'mek';
  if (isFalseFlag) return 'false_flag';
  const txt = String(analysisText || '');
  const idMatch = txt.match(/تشخیص هویت اکانت:\s*([^\n]+)/);
  const idLine = (idMatch ? idMatch[1] : txt).toLowerCase();

  // 1. Check normal citizen & suspicious accounts FIRST before checking 'سایبری'
  // (since citizen text contains "(فاقد شواهد سایبری یا سازمانی)")
  if (
    idLine.includes('کاربر عادی') ||
    idLine.includes('شهروند معمولی') ||
    idLine.includes('فاقد شواهد سایبری')
  ) {
    return 'citizen';
  }
  if (idLine.includes('حساب مشکوک') || idLine.includes('الگوی نزدیک به بات')) {
    return 'suspicious';
  }

  // 2. Political & Cyber Factions
  if (idLine.includes('مجاهدین') || idLine.includes('mek') || idLine.includes('رجوی') || idLine.includes('منافقین')) return 'mek';
  if (idLine.includes('قلابی') || idLine.includes('نفوذی') || idLine.includes('پرونده‌ساز') || idLine.includes('کمدساز') || idLine.includes('جفرسون') || idLine.includes('شارلاتان') || idLine.includes('پرستوی نظام')) return 'false_flag';
  if (idLine.includes('تجزیه') || idLine.includes('قوم‌گرا') || idLine.includes('جوانمردی')) return 'separatist';
  if (
    idLine.includes('ارزشی') ||
    idLine.includes('حامی جمهوری اسلامی') ||
    idLine.includes('سایبری حکومتی') ||
    idLine.includes('سایبری رژیم') ||
    idLine.includes('اکانت سایبری') ||
    idLine.includes('ارتش سایبری') ||
    idLine.includes('ولایی') ||
    idLine.includes('آیت‌الله بی‌بی‌سی') ||
    idLine.includes('ضعیفه رژیم') ||
    idLine.includes('افشاری') ||
    idLine.includes('بسیجی') ||
    idLine.includes('پروپاگاندای رژیم') ||
    idLine.includes('ارگان رسمی حکومت') ||
    idLine.includes('موش‌تباه') ||
    idLine.includes('رهبر مقوایی') ||
    idLine.includes('موش‌علی') ||
    idLine.includes('خامنه‌ای') ||
    idLine.includes('جلاد ۶۷') ||
    idLine.includes('لاریجانی') ||
    idLine.includes('قالیباف')
  ) return 'arzeshi';
  if (idLine.includes('اصلاح‌طلب') || idLine.includes('استمرارطلب') || idLine.includes('سازگارا') || idLine.includes('علیدوستی')) return 'eslahtalab';
  if (idLine.includes('چپ') || idLine.includes('چپول') || idLine.includes('۵۷ی')) return 'chapi';
  if (idLine.includes('پهلوی') || idLine.includes('ملی‌گرا') || idLine.includes('پادشاهی') || idLine.includes('شهبانو') || idLine.includes('مراد ویسی') || idLine.includes('مشروطه')) return 'pahlavi';
  if (idLine.includes('تیک خاکستری') || idLine.includes('نشان تایید خاکستری') || idLine.includes('حساب رسمی دولتی')) return 'government';
  if (idLine.includes('تیک طلایی') || idLine.includes('نشان تایید طلایی') || idLine.includes('سازمان رسمی') || idLine.includes('شرکت رسمی') || idLine.includes('شرکت ثبت‌شده') || idLine.includes('نهاد تجاری') || idLine.includes('organization')) return 'organization';
  if (idLine.includes('دیپلماتیک') || idLine.includes('وزارت امور خارجه')) return 'diplomatic';
  if (
    idLine.includes('روزنامه‌نگار') ||
    idLine.includes('خبرنگار') ||
    idLine.includes('رسانه') ||
    idLine.includes('خبرگزاری') ||
    idLine.includes('تلویزیونی') ||
    idLine.includes('پژوهشگر') ||
    idLine.includes('نویسنده') ||
    idLine.includes('طنزپرداز') ||
    idLine.includes('هنرمند') ||
    idLine.includes('فعال حقوق بشر') ||
    idLine.includes('آموزشکده') ||
    idLine.includes('نهاد مدنی')
  ) return 'media';
  return null;
}

/**
 * Builds the complete dictionary of known/custom/scanned accounts and restIds for timeline Mini-Badges
 */
async function buildBadgeDirectoryPayload() {
  const customMap = await getCustomAccountsMap();
  const scannedCache = await getScannedBadgesCache();
  const restIdReg = await getRestIdRegistry();
  const handleMap = {};

  // 1. Built-in KNOWN_AUTHENTIC_ENTITIES
  if (typeof KNOWN_AUTHENTIC_ENTITIES !== 'undefined') {
    for (const ent of KNOWN_AUTHENTIC_ENTITIES) {
      const isPahlaviEnt = /پادشاهی|ملی‌گرا|پهلوی|شهبانو/i.test(ent.identity || '');
      const isDipEnt = /دیپلماتیک/i.test(ent.identity || '');
      const fKey = isPahlaviEnt ? 'pahlavi' : (isDipEnt ? 'diplomatic' : 'media');
      for (const h of (ent.handles || [])) {
        const cleanH = normalizeEntityText(h);
        if (cleanH) handleMap[cleanH] = { faction: fKey, handle: `@${h}` };
      }
    }
  }

  // 2. Built-in MEK_HANDLES
  if (typeof MEK_HANDLES !== 'undefined') {
    for (const mh of MEK_HANDLES) {
      const cleanMh = normalizeEntityText(mh);
      if (cleanMh) handleMap[cleanMh] = { faction: 'mek', handle: `@${mh}` };
    }
  }

  // 3. Built-in KNOWN_POLITICAL_ACCOUNTS
  for (const item of KNOWN_POLITICAL_ACCOUNTS) {
    for (const h of (item.handles || [])) {
      const cleanH = normalizeEntityText(h);
      if (cleanH) {
        handleMap[cleanH] = { faction: item.faction, handle: `@${h}` };
      }
    }
  }

  // 4. Previously scanned accounts cache
  for (const [normH, entry] of Object.entries(scannedCache)) {
    if (normH && entry?.faction && !handleMap[normH]) {
      handleMap[normH] = {
        faction: entry.faction,
        handle: entry.handle || `@${normH}`,
        restId: entry.restId || ''
      };
    }
  }

  // 5. User-pinned custom accounts (Highest priority)
  for (const [normH, entry] of Object.entries(customMap)) {
    if (normH && entry?.faction) {
      handleMap[normH] = {
        faction: entry.faction,
        handle: entry.handle || `@${normH}`,
        restId: entry.restId || '',
        isCustom: true
      };
    }
  }

  // Sync restIdReg faction with authoritative handleMap (so newly added known/custom accounts override stale restId factions)
  for (const [, rEntry] of Object.entries(restIdReg)) {
    if (rEntry && rEntry.currentHandle) {
      const normCur = normalizeEntityText(rEntry.currentHandle);
      if (normCur && handleMap[normCur]?.faction) {
        rEntry.faction = handleMap[normCur].faction;
      }
    }
  }

  return {
    handleMap,
    restIdMap: restIdReg
  };
}

/**
 * Checks user-pinned custom accounts in storage, restId permanent tracking, AND hardcoded KNOWN_POLITICAL_ACCOUNTS
 */
async function matchPinnedOrKnownPoliticalAccount(username, displayName, restId = '') {
  const normHandle = normalizeEntityText(username);
  const normName = normalizeEntityText(displayName);
  const cleanRestId = String(restId || '').trim();

  const customMap = await getCustomAccountsMap();
  const restIdReg = await getRestIdRegistry();
  const regEntry = cleanRestId ? restIdReg[cleanRestId] : null;
  const previousHandles = Array.isArray(regEntry?.previousHandles)
    ? regEntry.previousHandles.filter(h => normalizeEntityText(h) !== normHandle)
    : [];

  const appendHandleChangeWarning = (reportObj) => {
    if (!reportObj || previousHandles.length === 0) return reportObj;
    const oldList = previousHandles.map(h => `@${String(h).replace(/^@/, '')}`).join(' ، ');
    const warnLine = `• ⚠️ هشدار تغییر نام کاربری (کشف با شناسه دائمی #${cleanRestId}): این اکانت پیش‌تر با آیدی ${oldList} فعالیت می‌کرده و برای فرار از شناسایی نام خود را تغییر داده است!`;
    return {
      ...reportObj,
      redFlags: `${warnLine}\n${reportObj.redFlags || ''}`,
      previousHandles,
      restId: cleanRestId
    };
  };

  // 1. Direct match in user-pinned custom accounts
  if (normHandle && customMap[normHandle]) {
    const entry = customMap[normHandle];
    return appendHandleChangeWarning(buildStandardFactionReport(
      entry.faction,
      entry.displayName || username,
      entry.note || 'گرایش این اکانت به صورت قطعی در حافظه X-Ray ثبت و قفل شده است.'
    ));
  }

  // 1-B. Match in custom accounts via permanent restId or previousHandles (Account renamed!)
  if (cleanRestId) {
    for (const [, entry] of Object.entries(customMap)) {
      if (entry && entry.restId && String(entry.restId) === cleanRestId) {
        return appendHandleChangeWarning(buildStandardFactionReport(
          entry.faction,
          entry.displayName || username,
          entry.note || `گرایش این اکانت (شناسه دائمی #${cleanRestId}) توسط شما ثبت شده است.`
        ));
      }
    }
    for (const prevH of previousHandles) {
      const normPrev = normalizeEntityText(prevH);
      if (normPrev && customMap[normPrev]) {
        const entry = customMap[normPrev];
        return appendHandleChangeWarning(buildStandardFactionReport(
          entry.faction,
          entry.displayName || username,
          entry.note || `این اکانت قبلاً با نام ${entry.handle || '@' + prevH} ثبت شده بود و نام کاربری خود را تغییر داده است.`
        ));
      }
    }
  }

  // 2. Check hardcoded KNOWN_POLITICAL_ACCOUNTS registry (current handle or previous handle via restId!)
  const handlesToCheck = [normHandle, ...previousHandles.map(h => normalizeEntityText(h))].filter(Boolean);
  for (const item of KNOWN_POLITICAL_ACCOUNTS) {
    for (const h of (item.handles || [])) {
      const cleanH = normalizeEntityText(h);
      if (cleanH && handlesToCheck.includes(cleanH)) {
        return appendHandleChangeWarning(buildStandardFactionReport(item.faction, displayName || username, item.note));
      }
    }
    for (const n of (item.names || [])) {
      const cleanN = normalizeEntityText(n);
      if (normName && cleanN && (normName === cleanN || (cleanN.length >= 6 && normName.includes(cleanN)))) {
        return appendHandleChangeWarning(buildStandardFactionReport(item.faction, displayName || username, item.note));
      }
    }
  }

  return null;
}

/**
 * Checks if account belongs to known authentic journalists, media, or prominent figures
 */
function matchKnownEntity(username, displayName, bio) {
  const normHandle = normalizeEntityText(username);
  const normName = normalizeEntityText(displayName);
  const normBio = normalizeEntityText(bio);

  // CRITICAL GUARD: If related to MEK, Terrorist Proxies, or Regime propaganda, NEVER classify as authentic media!
  const textToCheck = `${username || ''} ${displayName || ''} ${bio || ''}`;
  const isMek = /ایران\s*آزادی|سیمای\s*آزادی|مجاهدین|رجوی|شورای\s*ملی\s*مقاومت|ncri|pmoi|اشرف/i.test(textToCheck);
  if (isMek) return null;

  const isTerroristOrRegime = /حوثی|انصارالله|حزب‌الله|حزب\s*الله|قسام|حماس|المسراخ|خامنه‌ای|سپاه|وعده\s*صادق/i.test(textToCheck);
  if (isTerroristOrRegime) return null;

  // 1. Pass 1: Strict Handle Matching across all entities (Exact & prefix handle matching has highest specificity)
  for (const entity of KNOWN_AUTHENTIC_ENTITIES) {
    for (const h of entity.handles) {
      const cleanH = normalizeEntityText(h);
      if (normHandle && (normHandle === cleanH || (cleanH.length >= 7 && normHandle.startsWith(cleanH)))) {
        return entity;
      }
    }
  }

  // 2. Pass 2: Name Matching (Only if no handle matched in Pass 1)
  for (const entity of KNOWN_AUTHENTIC_ENTITIES) {
    for (const n of entity.names) {
      const cleanN = normalizeEntityText(n);
      if (normName && (normName === cleanN || (cleanN.length >= 8 && normName.includes(cleanN)))) {
        return entity;
      }
    }
  }

  // 3. Strict check for official diplomatic accounts only (removed loose 'تحلیلگر' heuristic that misclassified political activists)
  const isDiplomaticWord =
    normBio.includes('وزارتامورخارجه') ||
    normBio.includes('وزارتخارجه') ||
    normBio.includes('سفارت') ||
    normBio.includes('foreignministry') ||
    normName.includes('وزارتامورخارجه') ||
    normName.includes('سفارت') ||
    normName.includes('اسرائیلبهفارسی') ||
    normHandle.includes('israelpersian') ||
    normHandle.includes('usadarfarsi');

  if (isDiplomaticWord) {
    return {
      identity: '🌐 نهاد رسمی دیپلماتیک و دولتی بین‌المللی (حساب رسمی خارجی)',
      probability: '۰٪ (صفر درصد - حساب رسمی دیپلماتیک/دولتی تاییدشده)',
      redFlags: '• صفحه رسمی نمایندگی دیپلماتیک یا نهاد رسمی دولتی خارجی.\n• بازتاب مواضع رسمی دولت مربوطه.\n• فاقد هرگونه رفتار سایبری، بات یا ارتباط با فرقه مجاهدین خلق.',
      verdict: 'حساب رسمی دیپلماتیک و دولتی خارجی.'
    };
  }

  return null;
}

