/**
 * Converts Persian/Arabic digits to English digits and parses K/M/هزار/میلیون social counts
 */
function parseSocialCount(rawStr) {
  if (!rawStr) return null;
  const normalized = String(rawStr)
    .replace(/[۰-۹]/g, d => String('۰۱۲۳۴۵۶۷۸۹'.indexOf(d)))
    .replace(/[٠-٩]/g, d => String('٠١٢٣٤٥٦٧٨٩'.indexOf(d)))
    .replace(/,/g, '')
    .trim();

  const match = normalized.match(/(\d+(?:\.\d+)?)\s*(k|m|هزار|میلیون)?/i);
  if (!match) return null;
  let val = parseFloat(match[1]);
  const unit = (match[2] || '').toLowerCase();
  if (unit === 'k' || unit === 'هزار') val *= 1000;
  if (unit === 'm' || unit === 'میلیون') val *= 1000000;
  return Math.round(val);
}

/**
 * Idea #2: Structural Bot & Join-Date Forensics
 * Evaluates Join Date, Numeric Handle Suffixes, Follower/Following Ratio, and Hashtag Density
 */
function analyzeAccountStructuralForensics(accountInfo, hashtagFreqMap) {
  const username = (accountInfo.username || accountInfo.authorHandle || '').replace('@', '');
  const joinDateStr = accountInfo.joinDate || accountInfo.metadata || '';
  const followersNum = parseSocialCount(accountInfo.followersRaw);
  const followingNum = parseSocialCount(accountInfo.followingRaw);

  let botScore = 10; // Base score
  const clues = [];

  // 1. Numeric suffix handle pattern (e.g. aliatash884920, user19485732)
  const isNumericBotHandle = /^[a-zA-Z_]{2,14}[0-9]{5,10}$/.test(username);
  if (isNumericBotHandle) {
    botScore += 30;
    clues.push(`الگوی هندل عددی خودکار (@${username})`);
  }

  // 2. Join Date / Account Age Parsing (Gregorian 2009-2026 & Solar Hijri 1388-1405)
  const normJoin = String(joinDateStr)
    .replace(/[۰-۹]/g, d => String('۰۱۲۳۴۵۶۷۸۹'.indexOf(d)));
  let joinYear = null;
  const gregMatch = normJoin.match(/\b(200[6-9]|201[0-9]|202[0-6])\b/);
  const shamsiMatch = normJoin.match(/\b(138[5-9]|139[0-9]|140[0-5])\b/);
  if (gregMatch) {
    joinYear = parseInt(gregMatch[1], 10);
  } else if (shamsiMatch) {
    joinYear = parseInt(shamsiMatch[1], 10) + 621;
  }

  let isNewAccount = false;
  if (joinYear) {
    if (joinYear >= 2024) {
      isNewAccount = true;
      botScore += 20;
      clues.push(`اکانت تازه‌تاسیس (${joinYear})`);
    } else if (joinYear <= 2020) {
      botScore = Math.max(0, botScore - 10);
      clues.push(`اکانت باسابقه (تاسیس ${joinYear})`);
    }
  }

  // 3. Follower / Following Ratio
  if (followersNum !== null && followingNum !== null) {
    if (followersNum < 40 && followingNum > 600) {
      botScore += 25;
      clues.push(`نسبت مشکوک فالوئر به فالووینگ (${followersNum} دنبال‌کننده در برابر ${followingNum} دنبال‌شونده)`);
    } else if (followersNum > 5000 && followersNum > followingNum * 3) {
      botScore = Math.max(0, botScore - 10);
      clues.push(`مخاطبان ارگانیک بالا (${followersNum.toLocaleString()} دنبال‌کننده)`);
    }
  }

  // 4. Hashtag Stuffing Density
  const postCount = Math.max(1, accountInfo.observedTweetCount || 1);
  let totalTagUses = 0;
  if (hashtagFreqMap) {
    for (const v of hashtagFreqMap.values()) totalTagUses += v.count;
  }
  const avgTagsPerPost = totalTagUses / postCount;
  if (avgTagsPerPost >= 4.5 && postCount >= 3) {
    botScore += 20;
    clues.push(`تراکم غیرعادی هشتگ (${avgTagsPerPost.toFixed(1)} هشتگ در هر پست - الگوی کمپین سایبری)`);
  }

  if (accountInfo.isVerified) {
    if (accountInfo.isGreyBadge || accountInfo.verifiedType === 'Government') {
      clues.push('دارای نشان تایید خاکستری دولتی (Grey Checkmark)');
    } else if (accountInfo.isGoldBadge || accountInfo.verifiedType === 'Business') {
      clues.push('دارای نشان تایید طلایی سازمانی (Gold Checkmark)');
    } else {
      clues.push('دارای تیک آبی (Verified)');
    }
  }

  botScore = Math.min(98, Math.max(2, botScore));

  return {
    botScore,
    isNumericBotHandle,
    isNewAccount,
    joinYear,
    followersNum,
    followingNum,
    forensicBullet: clues.length > 0
      ? `• 🧬 کالبدشکافی ساختاری اکانت: ${clues.join(' | ')}`
      : ''
  };
}

/**
 * Deep Tweet-by-Tweet & Sentence-Level Text Stance Analyzer
 * Inspects the actual prose text of tweets (beyond raw hashtag counts) to detect:
 * 1) Hashtag Hijacking (e.g. putting #رضا_پهلوی or #پهلوی on anti-Pahlavi / anti-opposition tweets)
 * 2) Anti-Pahlavi text sentiment, mockery, and cyber slurs (#رضا_دادول, ربع پهلوی, شازده, etc.)
 * 3) Anti-Barandaz / Anti-Opposition text stance (attacking براندازها, جریان برانداز, اپوزیسیون)
 * 4) Regime Intelligence / Osolgara / Paydari security terminology (شبکه نفوذ, سرطان اصلاحات, etc.)
 */
function analyzeTweetTextStance(accountInfo, authorOwnTweetsText, identityHeaderText, hashtagFreqMap) {
  const fullText = `${identityHeaderText || ''}\n${authorOwnTweetsText || ''}`;
  const rawTweetSegments = String(authorOwnTweetsText || '')
    .split(/\n+|\[(?:پست|بازنشر)[^\]]*\]:?/g)
    .map(s => s.trim())
    .filter(s => s.length >= 8);

  let antiPahlaviTweetCount = 0;
  let proPahlaviTweetCount = 0;
  let antiBarandazTweetCount = 0;
  const antiPahlaviReasons = [];
  const antiBarandazReasons = [];
  const regimeIntelReasons = [];

  // 1. Direct Regime-Cyber / Leftist Slurs & Hostile Terms against Pahlavi
  const slurMatches = [];
  const slurDefinitions = [
    { re: /رضا[_\s‌]*دادول|رضادادول|\bدادول\b/i, label: 'رضا دادول' },
    { re: /ربع[_\s‌]*پهلوی/i, label: 'ربع پهلوی' },
    { re: /رضا[_\s‌]*دیبا|رضادیبا/i, label: 'رضا دیبا' },
    { re: /رضا[_\s‌]*پالانی|\bپالانی\b/i, label: 'پالانی' },
    { re: /توله[_\s‌]*شاه|بچه[_\s‌]*شاه/i, label: 'توله شاه' },
    { re: /پهلوی[_\s‌]*چی|پهلوی[_\s‌]*پرست/i, label: 'پهلوی‌چی/پهلوی‌پرست' },
    { re: /فرقه[_\s‌]*پهلوی|فرقه[_\s‌]*سلطنت|سیرک[_\s‌]*پهلوی|سیرک[_\s‌]*وکالت/i, label: 'فرقه/سیرک پهلوی' },
    { re: /پهلوی[_\s‌]*خائن|خاندان[_\s‌]*خیانت|وحوش[_\s‌]*پهلوی|نسل[_\s‌]*ساواک|قاتل[_\s‌]*تاریخ[_\s‌]*ایران/i, label: 'پهلوی خائن / خاندان خیانت' },
    { re: /فاشیسم[_\s‌]*سلطنتی|دیکتاتوری[_\s‌]*پهلوی|استبداد[_\s‌]*پهلوی/i, label: 'فاشیسم سلطنتی / دیکتاتوری پهلوی' },
    { re: /سلطنت[_\s‌]*طلبا\b|سلطنت[_\s‌]*طلب‌ها|سلطنت[_\s‌]*طلبان/i, label: 'سلطنت‌طلبان' }
  ];
  for (const item of slurDefinitions) {
    if (item.re.test(fullText)) {
      slurMatches.push(item.label);
    }
  }
  if (slurMatches.length > 0) {
    antiPahlaviTweetCount += slurMatches.length * 2;
    antiPahlaviReasons.push(`استفاده از القاب و هشتگ‌های تخریبی علیه شاهزاده رضا پهلوی و پادشاهی‌خواهان (${slurMatches.map(s => `«${s}»`).join('، ')})`);
  }

  // 2. Regime Intelligence / Security / Hardliner Osolgara Jargon in Bio or Tweets
  if (/شبکه\s*ی?\s*نفوذ|مبارزه\s*با\s*(?:شبکه\s*ی?\s*)?نفوذ|افشا(?:ی|\s*کردن)\s*شبکه\s*ی?\s*نفوذ|پروژه\s*نفوذ/i.test(fullText)) {
    regimeIntelReasons.push('به‌کارگیری کلیدواژه امنیتی-اطلاعاتی «شبکه نفوذ / مبارزه با شبکه نفوذ» در بیوگرافی یا متن پست‌ها');
  }
  if (/سرطان[_\s‌]*اصلاحات|افساد[_\s‌]*طلبان|غرب[‌\s]*گدا(?:یان)?|جنگ\s*شناختی|جهاد\s*تبیین/i.test(fullText)) {
    regimeIntelReasons.push('استفاده از ادبیات و هشتگ‌های جریان اصولگرا/پایداری و قرارگاه‌های سایبری رژیم (مانند «سرطان اصلاحات» / «افسادطلبان» / «جهاد تبیین»)');
  }

  const hasMojtabaOrShiaTag = Boolean(
    hashtagFreqMap && (
      hashtagFreqMap.has(normalizeHashtagKey('مجتبی_خامنه‌ای')) ||
      hashtagFreqMap.has(normalizeHashtagKey('مجتبی_خامنه_ای')) ||
      hashtagFreqMap.has(normalizeHashtagKey('شیعه'))
    )
  );
  if (hasMojtabaOrShiaTag && (slurMatches.length > 0 || regimeIntelReasons.length > 0)) {
    regimeIntelReasons.push('ترکیب هشتگ‌های مذهبی/حکومتی (#مجتبی_خامنه‌ای، #شیعه) با خط تخریب اپوزیسیون و پهلوی');
  }

  // 3. Tweet-by-Tweet & Sentence-by-Sentence Content Stance Analysis
  const pahlaviMentionRe = /رضا[_\s‌]*پهلوی|پهلوی|شاهزاده|شازده|شهبانو|فرح|یاسمین|سلطنت|پادشاهی|وکیل[_\s‌]*ملت|وکالت/i;
  const genuinePraiseRe = /جاوید\s*شاه|جاویدشاه|رضاشاه\s*روحت\s*شاد|درود\s*بر\s*(?:شاهزاده|رضا\s*پهلوی|خاندان\s*پهلوی|شهبانو)|همراهی\s*با\s*(?:شاهزاده|رضا\s*پهلوی)|حمایت\s*از\s*(?:شاهزاده|رضا\s*پهلوی)|پاینده\s*باد\s*شاهزاده|جانم\s*فدای\s*(?:شاهزاده|پهلوی|ایران)|پهلوی[_\s‌]*امید[_\s‌]*ملت|KingRezaPahlavi/i;
  const antiRegimeOrMekTargetRe = /مرگ\s*بر\s*(?:خامنه‌ای|خامنه ای|جمهوری\s*اسلامی|دیکتاتور|سپاه|آخوند|ولی\s*فقیه)|فرقه\s*تبهکار|فرقه\s*رجوی|منافقین\s*خلق|آلبانی[‌\s]*نشین|خامنه‌ای\s*(?:ضحاک|قاتل|جنایتکار)|رژیم\s*(?:کودک‌کش|اشغالگر|اسلامی|تبهکار)|جمهوری\s*اسلامی/i;
  const hostilePredicateRe = /خائن|خیانت|وطن[‌\s]*فروش|مزدور|نوکر|ارباب|کاسه[‌\s]*لیس|گدایی|دلقک|سیرک|دروغ|دروغگو|فریب|فریبکار|کلاهبردار|شارلاتان|توهم|متوهم|ورشکسته|بی[‌\s]*عرضه|بی[‌\s]*سواد|بی[‌\s]*عمل|بی[‌\s]*کاره|ترسو|بزدل|فراری|مفت[‌\s]*خور|ثروت\s*ملت|پول\s*ملت|میلیاردها\s*دلار|دزد|دزدی|غارت|فاسد|فساد|صهیونیست|نتانیاهو|موساد|سعودی|آل\s*سعود|تحریم[‌\s]*طلب|کاسب\s*تحریم|جنگ[‌\s]*طلب|تجزیه[‌\s]*طلب|پروژه|مهره|عروسک|خیمه[‌\s]*شب[‌\s]*بازی|شبکه\s*ی?\s*نفوذ|نفوذی|رسوا|رسوایی|ذلت|حقارت|شکست|لعنت|مرگ\s*بر|ننگ|وقاحت|وقیح|احمق|ابله|مضحک|مسخره|ادعا|مدعی|ساواک|فاشیست|فاشیسم|پوپولیست|ضد\s*ایران|برانداز/i;

  const directAntiPahlaviSentenceRe =
    /(?:رضا[_\s‌]*پهلوی|شازده|ربع[_\s‌]*پهلوی|سلطنت[_\s‌]*طلب(?:ها|ان|ا)?|حامیان\s*پهلوی|طرفداران\s*پهلوی|پروژه\s*وکالت)[^.!؟\n]{0,55}(?:خائن|خیانت|وطن[‌\s]*فروش|مزدور|دروغگو|دروغ|فریبکار|فریب|بی[‌\s]*عرضه|بی[‌\s]*سواد|بی[‌\s]*عمل|احمق|ابله|متوهم|توهم|ورشکسته|دلقک|سیرک|کاسه[‌\s]*لیس|نوکر|گدایی|عروسک|پروژه|مهره|نفوذ|موساد|صهیونیست|نتانیاهو|تحریم|کاسب|جنگ[‌\s]*طلب|تجزیه|فراری|مفت[‌\s]*خور|دزد|غارت|فاسد|وقاحت|رسوا|ذلت|حقارت|شکست|ساواک|فاشیست)/i;

  const reverseAntiPahlaviSentenceRe =
    /(?:خیانت|وطن[‌\s]*فروشی|مزدوری|دروغ(?:های)?|فریب(?:کاری)?|توهم(?:ات)?|سیرک|ورشکستگی|حماقت|بلاهت|بی[‌\s]*عرضگی|کاسه[‌\s]*لیسی|نوکری|پروژه|عروسک|دزدی|فساد|وقاحت|رسوایی|ذلت|حقارت)\s+(?:این\s+|همین\s+|جریان\s+|دار\s*و\s*دسته\s+|حامیان\s+|طرفداران\s+)?(?:رضا[_\s‌]*پهلوی|شازده|ربع[_\s‌]*پهلوی|سلطنت[_\s‌]*طلب(?:ها|ان|ا)?|حامیان\s*پهلوی)/i;

  const directAntiBarandazRe =
    /توهم\s*براندازی|رویای\s*براندازی|سیرک\s*برانداز(?:ی|ها|ان)?|سیرک\s*اپوزیسیون|پروژه\s*براندازی|کاسبان\s*براندازی|شغل\s*(?:شریف\s*)?براندازی|برانداز\s*جماعت|جماعت\s*برانداز|لشکر\s*برانداز|این\s*برانداز(?:ها|ان|ا)|برانداز(?:ها|ان|ا)ی?\s*(?:وطن[‌\s]*فروش|خائن|مزدور|فراری|خارج[‌\s]*نشین|احمق|ابله|متوهم|ورشکسته|بی[‌\s]*سواد|قلابی|فاسد|ساده[‌\s]*لوح|تدارکاتچی)|اپوزیسیون\s*(?:قلابی|ورشکسته|وطن[‌\s]*فروش|خائن|مزدور|فاسد|خارج[‌\s]*نشین|صادراتی|بی[‌\s]*آبرو|برانداز)|ضد\s*انقلاب|ضدانقلاب|معاندین|عناصر\s*معاند|اغتشاشگر(?:ان)?|فتنه[‌\s]*گر(?:ان)?/i;

  for (const seg of rawTweetSegments) {
    const proseWithoutTags = seg.replace(/#[\p{L}\p{N}_\u200C]+/gu, ' ').trim();
    const hasPraiseInSeg = genuinePraiseRe.test(seg);
    const targetsRegimeOrMekInSeg = antiRegimeOrMekTargetRe.test(seg);

    // Check Anti-Barandaz / Anti-Opposition content in this tweet
    const mentionsBarandaz = /\b(?:برانداز(?:ها|ان|ا|ی)?|جریان\s*برانداز|اپوزیسیون)\b/i.test(seg);
    const isSelfBarandaz = /من\s*براندازم|ما\s*برانداز(?:ها|ان|یم)|یک\s*برانداز\s*واقعی/i.test(seg);
    if (
      directAntiBarandazRe.test(seg) ||
      (mentionsBarandaz && !isSelfBarandaz && !hasPraiseInSeg && hostilePredicateRe.test(proseWithoutTags))
    ) {
      antiBarandazTweetCount++;
    }

    // Check Pahlavi stance in this tweet
    if (pahlaviMentionRe.test(seg)) {
      if (
        (/رضا[_\s‌]*دادول|ربع[_\s‌]*پهلوی|رضا[_\s‌]*دیبا|شازده|پهلوی[_\s‌]*چی|سلطنت[_\s‌]*طلبا/i.test(seg)) ||
        (!hasPraiseInSeg && (directAntiPahlaviSentenceRe.test(seg) || reverseAntiPahlaviSentenceRe.test(seg))) ||
        (!hasPraiseInSeg && !targetsRegimeOrMekInSeg && hostilePredicateRe.test(proseWithoutTags))
      ) {
        antiPahlaviTweetCount++;
      } else if (hasPraiseInSeg) {
        proPahlaviTweetCount++;
      }
    }
  }

  // Also check fullText for sentence-level anti-Pahlavi or anti-Barandaz if not praising Pahlavi
  const hasAnyGenuinePraise = proPahlaviTweetCount > 0 || genuinePraiseRe.test(fullText);
  if (!hasAnyGenuinePraise && (directAntiPahlaviSentenceRe.test(fullText) || reverseAntiPahlaviSentenceRe.test(fullText))) {
    antiPahlaviTweetCount = Math.max(antiPahlaviTweetCount, 1);
    antiPahlaviReasons.push('محتوای متنی توییت‌ها مستقیماً در حال تخریب، تمسخر یا حمله به شاهزاده رضا پهلوی و پادشاهی‌خواهان است');
  } else if (antiPahlaviTweetCount > 0 && antiPahlaviReasons.length === 0) {
    antiPahlaviReasons.push(`بررسی متن توییت‌ها (${antiPahlaviTweetCount} پست): ادبیات و جملات به کار رفته علیه شاهزاده رضا پهلوی و جریان پادشاهی‌خواهی است`);
  }

  if (directAntiBarandazRe.test(fullText) || antiBarandazTweetCount > 0) {
    antiBarandazTweetCount = Math.max(antiBarandazTweetCount, 1);
    antiBarandazReasons.push('موضع‌گیری متنی صریح علیه «براندازها / جریان برانداز و اپوزیسیون» در توییت‌ها (ادبیات هم‌سو با خط امنیتی رژیم)');
  }

  // 4. Detect Hashtag Hijacking (موج‌سواری سایبری روی هشتگ #رضا_پهلوی یا #پهلوی)
  const rezaPahlaviTagCount =
    (hashtagFreqMap?.get(normalizeHashtagKey('رضا_پهلوی'))?.count || 0) +
    (hashtagFreqMap?.get(normalizeHashtagKey('پهلوی'))?.count || 0) +
    (hashtagFreqMap?.get(normalizeHashtagKey('شاهزاده_رضا_پهلوی'))?.count || 0);

  const isHijackingPahlaviHashtags = Boolean(
    rezaPahlaviTagCount > 0 &&
    proPahlaviTweetCount === 0 &&
    (antiPahlaviTweetCount > 0 || antiBarandazTweetCount > 0 || slurMatches.length > 0 || regimeIntelReasons.length > 0)
  );

  return {
    antiPahlaviTweetCount,
    proPahlaviTweetCount,
    antiBarandazTweetCount,
    hasAntiPahlaviSlurs: slurMatches.length > 0,
    hasRegimeIntelOrHardlinerJargon: regimeIntelReasons.length > 0,
    isHijackingPahlaviHashtags,
    rezaPahlaviTagCount,
    antiPahlaviReasons,
    antiBarandazReasons,
    regimeIntelReasons
  };
}

/**
 * Multi-Signal Weighted Political Alignment & Forensic Scoring Engine
 * Evaluates Bio, Display Name, Emojis, Historical Hashtag Frequencies, Vocabulary,
 * Tweet-by-Tweet Text Stance, Hashtag Hijacking, Interaction Graph (Retweets vs Critical Quotes),
 * Structural Bot Forensics, and False-Flag Infiltrator Contradictions.
 */
function evaluateAccountAlignment(accountInfo, customAccountsMap = {}, options = {}) {
  const username = accountInfo.username || accountInfo.authorHandle || '';
  const displayName = accountInfo.displayName || '';
  const bio = accountInfo.bio || '';
  const userUrl = accountInfo.userUrl || '';
  const referencedHandles = accountInfo.referencedHandles || [];
  const retweetedHandles = accountInfo.retweetedHandles || [];
  const quotedInteractions = accountInfo.quotedInteractions || [];

  // CRITICAL: Only use the author's own words (authorOwnTextOnly / currentTweet), NEVER the text of a tweet they quoted!
  const recentTweetsJoined = Array.isArray(accountInfo.recentTweets) ? accountInfo.recentTweets.join('\n') : '';
  const authorOwnTweetsText = accountInfo.authorOwnTextOnly || accountInfo.currentTweet || accountInfo.tweetsSample || recentTweetsJoined || '';
  const identityHeaderText = `${username} ${displayName} ${bio}`;
  const fullAuthorCorpus = `${identityHeaderText}\n${authorOwnTweetsText}`;

  const normHandle = normalizeEntityText(username);

  // 0a. Official Diplomatic Mission / Embassy / Ministry of Islamic Republic of Iran
  // STRICT RULE: All Islamic Republic embassies, ministries (mfa.ir, gov.ir), diplomats and official state organs
  // are 100% REGIME (Arzeshi / Regime Official), NEVER benign foreign government or grey checkmark!
  if (isIranianRegimeOfficial(accountInfo)) {
    const regimeReport = getIranianRegimeOfficialReport(accountInfo);
    return {
      report: regimeReport,
      model: 'Regime Official Radar (ارگان‌ها و سفارت‌خانه‌های رسمی رژیم)',
      isMekAlert: false,
      isFalseFlag: false,
      isArzeshi: true,
      isGovernment: false
    };
  }

  // 0b. Official Foreign / International Government check (Genuine Grey Checkmark ONLY)
  // STRICT RULE: ONLY accounts that genuinely have a verified Grey Badge / Government status from Twitter/X
  // and are NOT Iranian regime entities belong to this category!
  const isStrictGovAccount = Boolean(
    !isIranianRegimeOfficial(accountInfo) &&
    (
      Boolean(accountInfo.isGreyBadge) ||
      accountInfo.verifiedType === 'Government' ||
      /تیک خاکستری|حساب رسمی دولتی|government\s*official|state-affiliated/i.test(accountInfo.governmentLabel || '') ||
      (accountInfo.isVerified && /president of the united states|prime minister|head of state|department of state|white house/i.test(bio))
    )
  );

  if (isStrictGovAccount) {
    const govReport = buildStandardFactionReport(
      'government',
      displayName || username,
      accountInfo.governmentLabel || 'حساب رسمی دولتی / حاکمیتی (تیک خاکستری)'
    );
    return {
      report: govReport,
      model: 'Government Verified (تیک خاکستری رسمی دولتها و مقامات خارجی)',
      isMekAlert: false,
      isFalseFlag: false,
      isGovernment: true
    };
  }

  // 0c. Official Organizations & Registered Businesses (Genuine Gold Checkmark ONLY)
  // Accounts that genuinely have verified Gold Badge (Business/Organization) and are NOT Iranian regime entities
  const isStrictGoldAccount = Boolean(
    !isStrictGovAccount &&
    !isIranianRegimeOfficial(accountInfo) &&
    (
      Boolean(accountInfo.isGoldBadge) ||
      accountInfo.verifiedType === 'Business' ||
      /تیک طلایی|سازمان رسمی|شرکت ثبت‌شده|verified organization|business/i.test(accountInfo.governmentLabel || '')
    )
  );

  if (isStrictGoldAccount) {
    const goldReport = buildStandardFactionReport(
      'organization',
      displayName || username,
      accountInfo.governmentLabel || 'سازمان رسمی / شرکت ثبت‌شده (تیک طلایی)'
    );
    return {
      report: goldReport,
      model: 'Verified Organization (تیک طلایی سازمان‌ها و شرکت‌های رسمی)',
      isMekAlert: false,
      isFalseFlag: false,
      isGoldBadge: true
    };
  }

  const hashtagFreqMap = buildAuthorHashtagFrequencyMap(fullAuthorCorpus, accountInfo.authorHashtags || []);
  const structural = analyzeAccountStructuralForensics(accountInfo, hashtagFreqMap);

  // 1. Direct Official MEK Handle or Official MEK Website Domain in Bio/Profile URL
  for (const h of MEK_HANDLES) {
    const cleanH = normalizeEntityText(h);
    if (normHandle && (normHandle === cleanH || (cleanH.length >= 7 && normHandle.includes(cleanH)))) {
      return {
        report: getMekReport(),
        model: 'MEK Cult Radar (رادار ضد فرقه مجاهدین خلق)',
        isMekAlert: true
      };
    }
  }
  for (const domain of MEK_DOMAINS) {
    const cleanDomain = domain.toLowerCase();
    if ((userUrl && userUrl.toLowerCase().includes(cleanDomain)) || (bio && bio.toLowerCase().includes(cleanDomain))) {
      return {
        report: getMekProxyReport(`لینک مستقیم به وب‌سایت رسمی فرقه رجوی در پروفایل (${domain})`),
        model: 'MEK Cult Radar (رادار ضد فرقه مجاهدین خلق)',
        isMekAlert: true
      };
    }
  }

  // 2. Match Hashtag Frequencies across all categories & Perform Deep Text Stance Analysis
  const pahlaviTags = matchCategoryHashtags(hashtagFreqMap, CATEGORY_HASHTAGS.pahlavi);
  const chapiTags = matchCategoryHashtags(hashtagFreqMap, CATEGORY_HASHTAGS.chapi);
  const arzeshiTags = matchCategoryHashtags(hashtagFreqMap, CATEGORY_HASHTAGS.arzeshi);
  const eslahtalabTags = matchCategoryHashtags(hashtagFreqMap, CATEGORY_HASHTAGS.eslahtalab);
  const mekExplicitTags = matchCategoryHashtags(hashtagFreqMap, CATEGORY_HASHTAGS.mekExplicit);
  const sepTags = matchCategoryHashtags(hashtagFreqMap, CATEGORY_HASHTAGS.tajziehTalab);
  const textStance = analyzeTweetTextStance(accountInfo, authorOwnTweetsText, identityHeaderText, hashtagFreqMap);

  const hasHostileTextAgainstPahlaviOrOpposition = Boolean(
    textStance.hasAntiPahlaviSlurs ||
    textStance.antiPahlaviTweetCount > 0 ||
    textStance.antiBarandazTweetCount > 0 ||
    textStance.hasRegimeIntelOrHardlinerJargon
  );

  // 3. Evaluate Nationalist / Monarchist (Pahlavi) Signals & Score
  let pahlaviScore = 0;
  const pahlaviEvidence = [];

  // 3a. Bio & Display Name Symbols (🦁, ☀️, 👑, جاوید شاه, پهلوی, مشروطه, ایران‌گرا, ملی‌گرا)
  const hasLionSunEmoji = /🦁|☀️|👑/.test(identityHeaderText);
  const hasBioPahlavi = /جاوید\s*شاه|جاویدشاه|پهلوی|رضاشاه|شاهزاده|مشروطه|شیر\s*و\s*خورشید|ایران\s*را\s*پس|ملی\s*گرا|ملی‌گرا|ایران\s*گرا|ایران‌گرا|kingrezapahlavi|miga/i.test(identityHeaderText);
  const hasNationalistMaskInBio =
    hasLionSunEmoji ||
    hasBioPahlavi ||
    /کوروش|داریوش|وطن‌پرست|وطن\s*پرست|میهن‌پرست|میهن\s*پرست|ایران‌دوست|چو\s*ایران\s*نباشد|پاینده\s*ایران/i.test(identityHeaderText);

  if (hasBioPahlavi && !hasHostileTextAgainstPahlaviOrOpposition) {
    pahlaviScore += 45;
    pahlaviEvidence.push('معرفی و هویت‌یابی صریح ملی‌گرایانه / پادشاهی‌خواه در بیوگرافی یا نام کاربری');
  }
  if (hasLionSunEmoji && !hasHostileTextAgainstPahlaviOrOpposition) {
    pahlaviScore += 25;
    pahlaviEvidence.push('استفاده از نمادهای ملی و پادشاهی (🦁☀️👑) در پروفایل');
  }

  // 3b. Historical Pahlavi / Nationalist Hashtags (ONLY counted when tweet text is NOT attacking Pahlavi or Barandaz!)
  if (pahlaviTags.matchedCount > 0 && !hasHostileTextAgainstPahlaviOrOpposition) {
    pahlaviScore += (pahlaviTags.matchedCount * 18) + (pahlaviTags.totalOccurrences * 6);
    pahlaviEvidence.push(`استفاده از هشتگ‌های پادشاهی‌خواهی و ملی در پست‌های اکانت: ${pahlaviTags.matchedTags.slice(0, 6).join('، ')}`);
  }

  // 3c. Explicit Pahlavi Praise & Nationalist Democratic Vocabulary in Posts (Guarded by Text Stance!)
  const hasExplicitPahlaviPraise =
    !hasHostileTextAgainstPahlaviOrOpposition &&
    /جاوید\s*شاه|جاویدشاه|رضاشاه\s*روحت\s*شاد|رضاشاه\s*بزرگ|رضاشاه\s*دوم|خاندان\s*ایران‌ساز|پادشاهی\s*مشروطه|پهلوی\s*امید\s*ملت|وکیل\s*ملت/i.test(fullAuthorCorpus);
  if (hasExplicitPahlaviPraise) {
    pahlaviScore += 30;
    pahlaviEvidence.push('حمایت صریح از شاهزاده رضا پهلوی، خاندان ایران‌ساز پهلوی و پادشاهی مشروطه در متن پست‌ها');
  } else if (!hasHostileTextAgainstPahlaviOrOpposition && textStance.proPahlaviTweetCount > 0) {
    pahlaviScore += 28;
    pahlaviEvidence.push('محتوای متنی توییت‌ها در حمایت و همراهی با شاهزاده رضا پهلوی و جنبش ملی');
  }

  // Democratic & National Solidarity Signals (Genuine Pro-Pahlavi Democrats)
  const hasDemocraticPahlaviSignals =
    !hasHostileTextAgainstPahlaviOrOpposition &&
    /من_وکالت_میدهم|من\s*وکالت\s*می‌دهم|پادشاهی\s*مشروطه|سکولار\s*دموکراسی|دموکراسی\s*پارلمانی|همبستگی\s*ملی|پیمان\s*نوین|وکیل\s*ملت/i.test(fullAuthorCorpus);
  if (hasDemocraticPahlaviSignals) {
    pahlaviScore += 20;
    pahlaviEvidence.push('پایبندی به اصول دموکراسی، مشروطه‌خواهی، همبستگی ملی و همراهی با شاهزاده رضا پهلوی');
  }

  // Authentic Iranian Nationalist terminology (Extract exact matched terms & block if attacking Pahlavi/Opposition)
  const nationalistVocabCandidates = [
    { re: /فرقه\s*تبهکار/i, label: 'فرقه تبهکار' },
    { re: /رژیم\s*اشغالگر\s*اسلامی/i, label: 'رژیم اشغالگر اسلامی' },
    { re: /جاویدنام/i, label: 'جاویدنام' },
    { re: /ایران\s*را\s*پس\s*می[‌\s]*گیریم/i, label: 'ایران را پس می‌گیریم' },
    { re: /انقلاب\s*شیروخورشید/i, label: 'انقلاب شیروخورشید' },
    { re: /انقلاب\s*ملی\s*ایران/i, label: 'انقلاب ملی ایران' },
    { re: /پرچم\s*شیر\s*و\s*خورشید/i, label: 'پرچم شیر و خورشید' }
  ];
  const matchedNationalistTerms = nationalistVocabCandidates
    .filter(item => item.re.test(fullAuthorCorpus))
    .map(item => `«${item.label}»`);
  const hasNationalistVocab = !hasHostileTextAgainstPahlaviOrOpposition && matchedNationalistTerms.length > 0;
  if (hasNationalistVocab) {
    pahlaviScore += 22;
    pahlaviEvidence.push(`به‌کارگیری ادبیات و واژگان جنبش ملی ایران در متن پست‌ها (${matchedNationalistTerms.join('، ')})`);
  }

  // Criticizing Leftists/57-ists ("چپول", "۵۷ی", "پنجاه و هفتی") or MEK ("فرقه رجوی", "آلبانی‌نشین", "منافقین")
  const isCriticizingChapiOr57 = /چپول|پنجاه\s*و\s*هفتی|۵۷ی|57ی|گلشیفتگان|صادراتی|استمرارطلب/i.test(fullAuthorCorpus);
  if (isCriticizingChapiOr57 && !hasHostileTextAgainstPahlaviOrOpposition) {
    pahlaviScore += 18;
    pahlaviEvidence.push('مرزبندی و نقد صریح جریان‌های چپول، ۵۷ی و استمرارطلب از موضع ملی‌گرایی');
  }

  const isCriticizingMek =
    /فرقه\s*رجوی|فرقه\s*مجاهدین|فرقه\s*تروریستی\s*مجاهدین|سایبری\s*رجوی|سایبری‌های\s*رجوی|آلبانی\s*نشین|آلبانی‌نشین|پیرمردهای\s*اشرف|تیرانا|مزدور\s*صدام|مجاهدین\s*خائن|رجوی\s*خائن|منافقین\s*خلق/i.test(fullAuthorCorpus) ||
    (/(مجاهدین|رجوی|اشرف|کانون\s*شورشی)/i.test(fullAuthorCorpus) && /(فرقه|تروریست|خائن|وطن‌فروش|وطن\s*فروش|مزدور|جنایتکار|منفور|لعنت|ننگ|حقه‌باز|شارلاتان|سایبری|دلقک|مسخره)/i.test(fullAuthorCorpus));

  if (isCriticizingMek && !hasHostileTextAgainstPahlaviOrOpposition) {
    pahlaviScore += 15;
    pahlaviEvidence.push('افشاگری و موضع‌گیری انتقادی علیه فرقه تروریستی رجوی (مجاهدین خلق)');
  }

  // Check if account attacks Pahlavi / Monarchy or Barandaz / Opposition in Tweet Text or Hashtags
  const isAttackingPahlavi =
    textStance.hasAntiPahlaviSlurs ||
    textStance.antiPahlaviTweetCount > 0 ||
    /پهلوی_خائن|خاندان_خیانت|وحوش_پهلوی|نسل_ساواک|قاتل_تاریخ_ایران|فاشیسم\s*سلطنتی|دیکتاتوری\s*پهلوی|ربع\s*پهلوی|رضا\s*دیبا|رضا[_\s‌]*دادول|رضادادول|پهلوی‌چی|سلطنت[_\s‌]*طلب‌ها|سلطنت[_\s‌]*طلبان|سلطنت[_\s‌]*طلبا|پهلوی\s*پرست/i.test(fullAuthorCorpus) ||
    /#(نه_شاه_نه_شیخ|نه_به_پهلوی|pahlaviausladen|سلطنت_طلبان|سلطنت_طلب|رضا_دادول|رضادادول|ربع_پهلوی)\b/i.test(fullAuthorCorpus) ||
    /(مرگ\s*بر|لعنت\s*بر|خیانت|جنایات|دزدی|فساد|مزدوری)\s*(شاه|پهلوی|رضاشاه|سلطنت|رضا\s*پهلوی)/i.test(fullAuthorCorpus) ||
    (/#(پهلوی|رضا_پهلوی|سلطنت_طلبان)\b/i.test(fullAuthorCorpus) && /#(موساد|داعش|تروریست|صهیونیست|رضا_دادول|سرطان_اصلاحات)\b/i.test(fullAuthorCorpus));

  // Check for "Fake Monarchist / Anti-Pahlavi Cyber IRGC" tactics (پادشاهی‌خواهان قلابی ضد شاهزاده رضا پهلوی):
  // Pretending to be royalist/nationalist ("پادشاهی‌خواهتر از شاه!") while attacking Prince Reza Pahlavi, Empress Farah, or Yasmine Pahlavi
  const isFakeMonarchistAttackingPahlavi =
    /ما\s*شاه\s*می‌خواهیم\s*نه\s*(رضا|وکیل)|ما\s*شاه\s*میخواهیم\s*نه\s*(رضا|وکیل)|رضاشاه\s*آری\s*رضا\s*پهلوی\s*نه|پادشاهی‌خواهیم\s*نه\s*پهلوی|پهلوی\s*سوم\s*نمی‌خواهیم/i.test(fullAuthorCorpus) ||
    /(رضا\s*پهلوی|شاهزاده|شازده)[\s\S]{0,45}(جمهوری‌خواه\s*شده|جمهوری\s*خواه\s*شده|چپ\s*شده|اصلاح‌طلب\s*شده|بی‌عرضه|بی\s*عرضه|بی‌عمل|بی\s*عمل|ترسو|مماشات|پروژه\s*است|فریبکار|ساده‌لوح|ول\s*معطل|کاره‌ای\s*نیست)/i.test(fullAuthorCorpus) ||
    /اطرافیان\s*(چپ|اصلاح‌طلب|مارکسیست|فاسد)\s*(شاهزاده|رضا\s*پهلوی)|حلقه\s*(اطرافیان|مماشات)\s*(شاهزاده|رضا\s*پهلوی)/i.test(fullAuthorCorpus) ||
    /(فرح\s*دیبا|یاسمین\s*ابتهاج|رضا\s*دیبا)[\s\S]{0,40}(۵۷|انقلاب|خائن|مسبب|چپ|کمونیست|مصدق)/i.test(fullAuthorCorpus);

  let mekScore = 0;
  const mekEvidence = [];
  let chapiScore = 0;
  const chapiEvidence = [];
  let arzeshiScore = 0;
  const arzeshiEvidence = [];
  let eslahtalabScore = 0;
  const eslahtalabEvidence = [];
  let sepScore = 0;
  const sepEvidence = [];
  let falseFlagScore = 0;
  const falseFlagEvidence = [];

  if (textStance.isHijackingPahlaviHashtags) {
    const hijackBullet = `🚨 موج‌سواری سایبری روی هشتگ‌ها: استفاده ابزاری از هشتگ #رضا_پهلوی (${Math.ceil(textStance.rezaPahlaviTagCount)} بار) در حالی که محتوای متن توییت‌ها در جهت تخریب شاهزاده رضا پهلوی و ضدیت با جریان براندازان است`;
    arzeshiEvidence.push(hijackBullet);
    falseFlagEvidence.push(hijackBullet);
  }

  for (const r of textStance.antiPahlaviReasons) {
    arzeshiEvidence.push(r);
    falseFlagEvidence.push(r);
  }
  for (const r of textStance.antiBarandazReasons) {
    arzeshiEvidence.push(r);
    falseFlagEvidence.push(r);
  }
  for (const r of textStance.regimeIntelReasons) {
    arzeshiEvidence.push(r);
  }

  if (isFakeMonarchistAttackingPahlavi) {
    falseFlagScore += 75;
    falseFlagEvidence.push('استفاده از ادبیات «پادشاهی‌خواهان قلابی ضد پهلوی» (تخریب شاهزاده رضا پهلوی و شهبانو فرح با ژست سلطنت‌طلبی/ملی‌گرایی در راستای خط سایبری ج.ا.)');
  }
  if (hasNationalistMaskInBio && (isAttackingPahlavi || textStance.antiBarandazTweetCount > 0)) {
    falseFlagScore += 55;
  }

  // 3d. Idea #1: Interaction Graph Analysis (Retweet Endorsements vs. Critical Quotes)
  for (const rt of retweetedHandles) {
    const resolved = resolveHandleFaction(rt.handle, customAccountsMap);
    if (!resolved) continue;
    const countBoost = Math.min(3, rt.count || 1);
    if (resolved.faction === 'pahlavi' || resolved.faction === 'farah') {
      pahlaviScore += 24 * countBoost;
      pahlaviEvidence.push(`بازنشر (Retweet) و تایید اکانت شناخته‌شده ملی‌گرا و همراه پهلوی (${resolved.label})`);
    } else if (resolved.faction === 'false_flag') {
      falseFlagScore += 45 * countBoost;
      falseFlagEvidence.push(`بازنشر مستقیم اکانت شناخته‌شده پادشاهی‌خواه قلابی / ضد پهلوی (${resolved.label})`);
    } else if (resolved.faction === 'mek') {
      mekScore += 45 * countBoost;
      mekEvidence.push(`بازنشر مستقیم اکانت وابسته به فرقه مجاهدین خلق (${resolved.label})`);
    } else if (resolved.faction === 'arzeshi' || resolved.faction === 'khamenei' || resolved.faction === 'mojtaba' || resolved.faction === 'raisi' || resolved.faction === 'larijani' || resolved.faction === 'ghalibaf' || resolved.faction === 'bbcpersian' || resolved.faction === 'kohnavard') {
      arzeshiScore += 35 * countBoost;
      arzeshiEvidence.push(`بازنشر اکانت حکومتی/ارزشی یا رسانه صادراتی رژیم (${resolved.label})`);
    } else if (resolved.faction === 'eslahtalab' || resolved.faction === 'alidoosti' || resolved.faction === 'afshari' || resolved.faction === 'sazegara') {
      eslahtalabScore += 30 * countBoost;
      eslahtalabEvidence.push(`بازنشر اکانت طیف اصلاح‌طلب/استمرارطلب یا مدافع خط نظام (${resolved.label})`);
    } else if (resolved.faction === 'chapi' || resolved.faction === 'mohammadi' || resolved.faction === 'toomaj' || resolved.faction === 'golshifteh' || resolved.faction === 'boniadi' || resolved.faction === 'esmaeilion' || resolved.faction === 'golroo' || resolved.faction === 'rahmani' || resolved.faction === 'modarres') {
      chapiScore += 30 * countBoost;
      eslahtalabScore += 20 * countBoost;
      chapiEvidence.push(`بازنشر اکانت طیف چپ/اصلاح‌طلب یا چهره شبهه‌دار (${resolved.label})`);
    } else if (resolved.faction === 'separatist' || resolved.faction === 'javanmardi') {
      sepScore += 35 * countBoost;
      sepEvidence.push(`بازنشر اکانت تجزیه‌طلب (${resolved.label})`);
    }
  }

  let quotedAttackOnPahlavi = false;
  for (const qi of quotedInteractions) {
    const resolved = resolveHandleFaction(qi.targetHandle, customAccountsMap);
    if (!resolved) continue;
    const comment = qi.comment || '';
    const isCriticalComment =
      /خائن|مزدور|تروریست|فرقه|دروغگو|شارلاتان|وطن‌فروش|وطن\s*فروش|جنایتکار|سایبری|دلقک|مسخره|وقاحت|شرم|لعنت|ننگ|چپول|۵۷ی|استمرارطلب|آخوند|بی‌عرضه|بی\s*عرضه|بی‌عمل|بی\s*عمل|شازده|دیبا|پروژه/i.test(comment);
    const isSupportiveComment =
      /درود|دمت\s*گرم|تایید|احسنت|دقیقا|حق\s*مطلب|زنده\s*باد|پاینده|جاوید/i.test(comment) && !isCriticalComment;

    if (resolved.faction === 'pahlavi' || resolved.faction === 'farah') {
      if (isCriticalComment) {
        pahlaviScore -= 80;
        quotedAttackOnPahlavi = true;
        if (hasNationalistMaskInBio) {
          falseFlagScore += 55;
          falseFlagEvidence.push(`کوت تخریبی و تفرقه‌افکنانه علیه اکانت ملی/پهلوی (${resolved.label}) با وجود نقاب ملی‌گرایی در پروفایل`);
        } else {
          chapiScore += 20;
        }
      } else if (isSupportiveComment) {
        pahlaviScore += 22;
        pahlaviEvidence.push(`کوت حمایتی و تاییدآمیز از اکانت ملی‌گرا و همراه پهلوی (${resolved.label})`);
      }
    } else if (resolved.faction === 'false_flag' || resolved.faction === 'ronaghi') {
      if (isCriticalComment) {
        pahlaviScore += 18;
        pahlaviEvidence.push(`افشاگری و کوت انتقادی علیه اکانت پادشاهی‌خواه قلابی/نفوذی (${resolved.label})`);
      } else if (isSupportiveComment) {
        falseFlagScore += 40;
        falseFlagEvidence.push(`کوت حمایتی از اکانت پادشاهی‌خواه قلابی / ضد پهلوی (${resolved.label})`);
      }
    } else if (['mek', 'arzeshi', 'khamenei', 'mojtaba', 'raisi', 'larijani', 'ghalibaf', 'bbcpersian', 'kohnavard', 'eslahtalab', 'chapi', 'separatist', 'mohammadi', 'toomaj', 'golshifteh', 'boniadi', 'esmaeilion', 'golroo', 'rahmani', 'alidoosti', 'afshari', 'modarres', 'sazegara', 'javanmardi'].includes(resolved.faction)) {
      if (isCriticalComment || pahlaviScore >= 20) {
        pahlaviScore += 16;
        pahlaviEvidence.push(`موضع‌گیری و کوت انتقادی علیه اکانت ${resolved.label}`);
      } else if (isSupportiveComment) {
        if (resolved.faction === 'mek') mekScore += 35;
        if (resolved.faction === 'arzeshi' || resolved.faction === 'khamenei' || resolved.faction === 'mojtaba' || resolved.faction === 'raisi' || resolved.faction === 'larijani' || resolved.faction === 'ghalibaf' || resolved.faction === 'bbcpersian' || resolved.faction === 'kohnavard') arzeshiScore += 30;
        if (resolved.faction === 'eslahtalab' || resolved.faction === 'alidoosti' || resolved.faction === 'afshari' || resolved.faction === 'sazegara') eslahtalabScore += 25;
        if (resolved.faction === 'chapi' || resolved.faction === 'mohammadi' || resolved.faction === 'toomaj' || resolved.faction === 'golshifteh' || resolved.faction === 'boniadi' || resolved.faction === 'esmaeilion' || resolved.faction === 'golroo' || resolved.faction === 'rahmani' || resolved.faction === 'modarres') chapiScore += 25;
        if (resolved.faction === 'separatist' || resolved.faction === 'javanmardi') sepScore += 30;
      }
    }
  }

  if (
    isAttackingPahlavi ||
    isFakeMonarchistAttackingPahlavi ||
    quotedAttackOnPahlavi ||
    falseFlagScore >= 45 ||
    hasHostileTextAgainstPahlaviOrOpposition
  ) {
    pahlaviScore = -200; // Disqualify from Genuine Pro-Pahlavi Nationalist
  }

  // 4. Evaluate MEK (Mojahedin-e Khalq) Signals WITH STRICT ANTI-FALSE-POSITIVE GUARDS
  if (!isCriticizingMek && pahlaviScore < 20) {
    if (mekExplicitTags.matchedCount > 0) {
      mekScore += (mekExplicitTags.matchedCount * 35) + (mekExplicitTags.totalOccurrences * 10);
      mekEvidence.push(`استفاده از هشتگ‌های سازمانی فرقه رجوی: ${mekExplicitTags.matchedTags.join('، ')}`);
    }

    const isProMekEndorsement =
      /رئیس\s*جمهور\s*برگزیده\s*مقاومت|طرح\s*۱۰\s*ماده‌ای\s*خانم\s*مریم\s*رجوی|درود\s*بر\s*(مریم|مسعود)\s*رجوی|کانون‌های\s*شورشی\s*قهرمان|ارتش\s*آزادیبخش\s*ملی\s*ایران|سیمای\s*آزادی\s*تلویزیون\s*ملی/i.test(fullAuthorCorpus) ||
      (/ایران\s*آزادی|سیمای\s*آزادی|شورای\s*ملی\s*مقاومت|کانون\s*شورشی|اشرف\s*۳/i.test(identityHeaderText));

    if (isProMekEndorsement) {
      mekScore += 80;
      mekEvidence.push('ترویج مستقیم ادبیات سازمانی، شعارها و سران فرقه رجوی (شورای ملی مقاومت / کانون‌های شورشی)');
    }

    const hasAntiExecFrontTag = /stopexecution|نه_به_اعدام|سه_شنبه_های_نه_به_اعدام|سه‌شنبه‌های_نه_به_اعدام/i.test(fullAuthorCorpus);
    const hasMekBoilerplate = /دفاع از حقوق بشر بدون دفاع از حق حیات|پایان مجازات اعدام باید بخشی جدایی‌ناپذیر|قیام تا سرنگونی/i.test(fullAuthorCorpus);
    const referencesMekHandle = referencedHandles.some(ref => {
      const cleanRef = normalizeEntityText(ref);
      return MEK_HANDLES.some(mh => normalizeEntityText(mh) === cleanRef);
    });

    if (hasMekBoilerplate || (structural.isNumericBotHandle && hasAntiExecFrontTag && referencesMekHandle)) {
      mekScore += 75;
      mekEvidence.push('الگوی بات‌فارم تیرانا (اشرف ۳): هندل عددی سایبری + بازنشر کمپین‌های پوششی فرقه رجوی');
    } else if (referencesMekHandle && hasAntiExecFrontTag && pahlaviScore <= 0) {
      mekScore += 60;
      mekEvidence.push('هم‌پوشانی و بازنشر مستقیم اکانت‌های سایبری سازمان مجاهدین خلق');
    }
  }

  // 5. Evaluate Leftist / Chapi (چپ و چپول) Signals WITH STRICT GUARDS
  if (chapiTags.matchedCount > 0) {
    chapiScore += (chapiTags.matchedCount * 22) + (chapiTags.totalOccurrences * 6);
    chapiEvidence.push(`استفاده از هشتگ‌های ایدئولوژیک چپ و ضدپادشاهی: ${chapiTags.matchedTags.slice(0, 5).join('، ')}`);
  }

  const hasBioChapi = /کمونیست|سوسیالیست|مارکسیست|آنارشیست|چپ\s*گرا|چپ‌گرا|طبقه\s*کارگر|نه\s*شاه\s*نه\s*شیخ|communist|socialist|marxist|anarchist/i.test(identityHeaderText);
  if (hasBioChapi) {
    chapiScore += 45;
    chapiEvidence.push('معرفی صریح با عناوین چپ / سوسیالیست / مارکسیست / ضدپادشاهی در بیوگرافی');
  }

  // WLF ("زن زندگی آزادی"), Radical Feminist, Queer, or Anti-Monarchy Rights Bio Signals
  const hasBioWLF = /زن[،\s]*زندگی[،\s]*آزادی|woman[\s,]*life[\s,]*freedom|jin[\s,]*jiyan[\s,]*azadi|ژن[،\s]*ژیان[،\s]*ئازادی/i.test(identityHeaderText);
  const hasBioFeministOrQueer = /فمینیست|فمینیسم|feminist|feminism|کوئیر|queer|lgbt|ستم\s*مضاعف|عدالت\s*انتقالی/i.test(identityHeaderText);

  if (hasBioWLF && (hasBioFeministOrQueer || isAttackingPahlavi || hasChapiIdeologyText) && pahlaviScore < 20) {
    chapiScore += 50;
    chapiEvidence.push('استفاده ابزاری از شعار «زن، زندگی، آزادی» / فمینیسم در بیوگرافی هم‌راستا با مواضع چپ و تقابل با پادشاهی');
  } else if (hasBioFeministOrQueer && !hasLionSunEmoji && pahlaviScore < 15) {
    chapiScore += 32;
    chapiEvidence.push('گرایش فمینیستی و چپ نو در بیوگرافی در غیاب نمادها یا مبانی ملی‌گرایی');
  } else if (hasBioWLF && pahlaviScore < 15 && !hasLionSunEmoji && !hasBioPahlavi) {
    chapiScore += 26;
    chapiEvidence.push('استفاده از شعار «زن، زندگی، آزادی» در بیوگرافی بدون نمادهای شیر و خورشید یا هشتگ‌های پادشاهی‌خواهی');
  }

  const hasChapiIdeologyText =
    /طبقه\s*کارگر|بورژوازی|پرولتاریا|انقلاب\s*شورایی|لغو\s*کار\s*مزدی|سرمایه‌داری\s*جهانی|حزب\s*کمونیست|فداییان\s*خلق|حکمتیست|فاشیسم\s*سلطنتی|سلطنت‌طلب‌ها|دیکتاتوری\s*پهلوی|نه\s*شاه\s*نه\s*شیخ/i.test(fullAuthorCorpus);

  if (hasChapiIdeologyText && !isCriticizingChapiOr57) {
    chapiScore += 28;
    chapiEvidence.push('به‌کارگیری واژگان مارکسیستی/سوسیالیستی یا تقابل ایدئولوژیک با پادشاهی پهلوی');
  }

  if (isAttackingPahlavi && (hasBioWLF || hasBioFeministOrQueer || hasBioChapi) && pahlaviScore < 20) {
    chapiScore += 35;
    chapiEvidence.push('هجمه و تخریب پادشاهی پهلوی و شاهزاده رضا پهلوی از خاستگاه گفتمان چپ و فمینیسم ۵۷ی');
  }

  // CRITICAL GUARD: If the account has strong Nationalist/Pahlavi signals and does not attack Pahlavi, NEVER classify as Chapi!
  if (pahlaviScore >= 20 && !isAttackingPahlavi) {
    chapiScore = 0;
  }

  // 6. Evaluate Regime Supporter (Arzeshi 3-A & Eslahtalab 3-B)
  const isExplicitlyAntiRegime =
    /مرگ\s*بر\s*(خامنه‌ای|خامنه ای|جمهوری\s*اسلامی|دیکتاتور|سپاه|آخوند|ولی\s*فقیه|اصل\s*ولایت)|فرقه\s*تبهکار|خامنه‌ای\s*(جنایتکار|ضحاک|خائن|قاتل)|سپاه\s*تروریستی|رژیم\s*کودک‌کش|رژیم\s*اشغالگر/i.test(fullAuthorCorpus);

  if (!isExplicitlyAntiRegime && pahlaviScore < 40) {
    const isTerrorProxy =
      /نیروهای\s*مسلح\s*یمن|انصارالله|المسراخ|سید\s*عبدالملک|طوفان\s*الاقصی|کتائب\s*القسام|ابوعبیده/i.test(fullAuthorCorpus) ||
      (/حزب‌الله|حزب\s*الله/i.test(fullAuthorCorpus) && /سید\s*حسن|شهید\s*نصرالله|مقاومت\s*اسلامی/i.test(fullAuthorCorpus));

    if (isTerrorProxy) {
      return {
        report: {
          identity: '🔴 ارتش سایبری رژیم و مروج تروریسم (حامی حوثی‌ها و حزب‌الله)',
          probability: '۹۵٪ (بسیار بالا - ترول و بوقچی تروریسم نیابتی رژیم)',
          redFlags: '• بازنشر مستقیم ادعاها و پروپاگاندای جنگی گروه‌های تروریستی نیابتی سپاه پاسداران (حوثی‌های یمن، حزب‌الله، حماس).\n• استفاده از نشانه‌ها، پرچم‌ها و هشتگ‌های اتاق‌های فکر تروریسم منطقه‌ای رژیم.',
          verdict: 'بوقچی تروریسم و بازوی سایبری سپاه؛ فوراً بلاک و ریپورت کنید.'
        },
        model: 'Regime Radar (رادار ارزشی و حامیان حکومت)',
        isMekAlert: false
      };
    }

    // Official Islamic Republic Emblem (☫ / U+262B) in Display Name or Bio
    if (/☫|\u262B/.test(identityHeaderText)) {
      arzeshiScore += 50;
      arzeshiEvidence.push('استفاده از نشان رسمی حکومت جمهوری اسلامی (☫) در نام نمایشی یا بیوگرافی اکانت');
    }

    if (arzeshiTags.matchedCount > 0) {
      arzeshiScore += (arzeshiTags.matchedCount * 28) + (arzeshiTags.totalOccurrences * 8);
      arzeshiEvidence.push(`استفاده از هشتگ‌های ارزشی و ولایی رژیم: ${arzeshiTags.matchedTags.slice(0, 5).join('، ')}`);
    }

    const hasExplicitVelayatiPraise =
      /امام\s*خامنه‌ای|حضرت\s*آقا|آقا\s*سید\s*علی|رهبر\s*معظم|مقام\s*معظم\s*رهبری|جان\s*ولی\s*فقیه|فدای\s*(رهبر|آقا|ولایت)|نائب\s*امام\s*زمان|لبیک\s*یا\s*خامنه‌ای|سرباز\s*ولایت|مدافعان\s*حرم|حاج\s*قاسم|شهید\s*سلیمانی|شهید\s*رئیسی|وعده\s*صادق/i.test(fullAuthorCorpus) ||
      (/(ولی\s*فقیه|ولایت\s*فقیه)/i.test(fullAuthorCorpus) && /(جان|رهبر|خط\s*قرمز|حرم|اطاعت|سرباز|فدا|ستون|حفظ)/i.test(fullAuthorCorpus) && !/(مرگ\s*بر|نابود|سقوط|طاعون|دیکتاتور|استبداد|جنایت)/i.test(fullAuthorCorpus));

    if (hasExplicitVelayatiPraise) {
      arzeshiScore += 55;
      arzeshiEvidence.push('ستایش مستقیم از خامنه‌ای، ولایت فقیه، قاسم سلیمانی، سپاه پاسداران یا عملیات‌های رژیم');
    }

    // Regime Martyrdom Vocabulary ("به شهادت رسید" / "شهدای امنیت" / praising regime police/IRGC forces as martyrs)
    const hasRegimeMartyrdomVocab =
      /به\s*شهادت\s*رسید|به\s*فیض\s*شهادت|درجه\s*رفیع\s*شهادت|شهدای\s*(امنیت|مدافع\s*حرم|فراجا|مرزبانی|فاطمیون|زینبیون|قدس|اقتدار)|شهید\s*(مدافع\s*امنیت|مدافع\s*حرم|فراجا|مرزبانی)/i.test(fullAuthorCorpus) ||
      (/\bشهید\s+[\u0600-\u06FF\s]{3,28}(به\s*شهادت|شهادت\s*رسید|توسط\s*تروریست)/i.test(fullAuthorCorpus));

    if (hasRegimeMartyrdomVocab && !hasNationalistVocab) {
      arzeshiScore += 60;
      arzeshiEvidence.push('استفاده از ادبیات رسمی حکومت و نیروهای امنیتی/انتظامی رژیم («شهید ... به شهادت رسید» / «شهدای امنیت») به جای واژگان ملی مانند جاویدنام');
    }

    // Regime Cyber Smear Campaigns against Monarchists & Iran International (#سلطنت_طلبان, #موساد, #اینترنشنال, #تروریست)
    const hasRegimeSmearTags =
      /سعودی[_\s‌]*اینترنشنال/i.test(fullAuthorCorpus) ||
      (/#(سلطنت_طلبان|سلطنت_طلب|پهلوی|اینترنشنال)\b/i.test(fullAuthorCorpus) && /#(موساد|داعش|تروریست|صهیونیست)\b/i.test(fullAuthorCorpus));

    if (hasRegimeSmearTags) {
      arzeshiScore += 55;
      arzeshiEvidence.push('خط تخریبی سایبری رژیم علیه پادشاهی‌خواهان و رسانه‌های مخالف (ترکیب هشتگ‌های #سلطنت_طلبان، #اینترنشنال، #موساد و #تروریست)');
    }

    // Axis-of-Resistance / IRGC War & Missile Propaganda
    const hasRegimeWarPropaganda =
      /فرودگاه\s*(ریاض|بن\s*گوریون|بن‌گوریون)|موشک[‌\s]*باران\s*(تل\s*آویو|تل‌آویو|حیفا|ریاض)|محور\s*مقاومت|سپاه\s*قدس|حشدالشعبی/i.test(fullAuthorCorpus);

    if (hasRegimeWarPropaganda) {
      arzeshiScore += 35;
      arzeshiEvidence.push('بازنشر خبرسازی‌ها و پروپاگاندای جنگی/موشکی محور مقاومت و کانال‌های سایبری سپاه');
    }

    // Text-Based Anti-Pahlavi Slurs, Regime Intelligence Jargon, Anti-Barandaz Stance & Hashtag Hijacking
    if (textStance.hasAntiPahlaviSlurs) {
      arzeshiScore += 55;
    }
    if (textStance.hasRegimeIntelOrHardlinerJargon) {
      arzeshiScore += 55;
    }
    if (textStance.antiBarandazTweetCount > 0) {
      arzeshiScore += 45 + Math.min(30, textStance.antiBarandazTweetCount * 12);
    }
    if (textStance.antiPahlaviTweetCount > 0 && (textStance.antiBarandazTweetCount > 0 || textStance.hasRegimeIntelOrHardlinerJargon || textStance.isHijackingPahlaviHashtags)) {
      arzeshiScore += 40;
    } else if (textStance.antiPahlaviTweetCount >= 2 && chapiScore === 0 && mekScore === 0) {
      arzeshiScore += 42;
    }

    const sentences = fullAuthorCorpus.split(/[\n.!؟]+/);
    for (const s of sentences) {
      if (/بقایی|اسماعیل\s*بقایی|عراقچی|امیرعبداللهیان|رئیسی|قالیباف|سعید\s*جلیلی|سپاه\s*پاسداران/i.test(s) &&
          /درود\s*بر|خدا\s*قوت|دمت\s*گرم|شرف|بزرگ\s*مرد|افتخار|دلاور|مقتدر|قهرمان|حاضر\s*جوابی/i.test(s) &&
          !/خائن|جنایتکار|تروریست|دروغگو|مزدور|قاتل|لعنت/i.test(s)) {
        arzeshiScore += 45;
        arzeshiEvidence.push('تمجید و جانبداری از مقامات، دیپلمات‌ها یا نهادهای نظامی جمهوری اسلامی');
        break;
      }
    }

    if (eslahtalabTags.matchedCount > 0) {
      eslahtalabScore += (eslahtalabTags.matchedCount * 25) + (eslahtalabTags.totalOccurrences * 6);
      eslahtalabEvidence.push(`استفاده از هشتگ‌های جبهه اصلاحات و استمرارطلبی: ${eslahtalabTags.matchedTags.slice(0, 5).join('، ')}`);
    }
    if (/جبهه\s*اصلاحات|آذر\s*منصوری|سید\s*محمد\s*خاتمی|مسعود\s*پزشکیان|محمدجواد\s*ظریف|روزنه‌گشایی|دولت\s*وفاق/i.test(fullAuthorCorpus) &&
        !/خائن|شارلاتان|مزدور|سوپاپ\s*اطمینان|اصلاحات\s*مرده|لعنت|کودتا|مترسک|وفاقی‌ها|سیب‌زمینی|خلبانی|سرطان[_\s‌]*اصلاحات/i.test(fullAuthorCorpus)) {
      eslahtalabScore += 40;
      eslahtalabEvidence.push('حمایت از چهره‌های جبهه اصلاحات، دولت پزشکیان/خاتمی و گفتمان حفظ نظام');
    }
  }

  // Disqualify Pahlavi score if strong Regime/Arzeshi evidence is present
  if (arzeshiScore >= 40) {
    pahlaviScore = -200;
  }

  // Deduplicate evidence lists
  const uniqueList = (arr) => Array.from(new Set(arr));

  // 7. Evaluate Separatist (تجزیه‌طلب‌ها) WITH PATRIOTIC UNITY GUARD
  const isPatrioticUnityContext = /از\s*(کردستان|کوردستان)\s*تا\s*(بلوچستان|خوزستان)|جانم\s*فدای\s*ایران|تمامیت\s*ارضی\s*ایران|ایران\s*یکپارچه/i.test(fullAuthorCorpus);

  if (!isPatrioticUnityContext && pahlaviScore < 30 && arzeshiScore < 40) {
    if (sepTags.matchedCount > 0) {
      sepScore += (sepTags.matchedCount * 28) + (sepTags.totalOccurrences * 8);
      sepEvidence.push(`استفاده از هشتگ‌های تجزیه‌طلبانه و قوم‌گرایانه: ${sepTags.matchedTags.slice(0, 5).join('، ')}`);
    }
    if (/روژهلات|کردستان\s*شرقی|آذربایجان\s*جنوبی|گونئی\s*آذربایجان|الاحواز|عربستان\s*اشغالی|بلوچستان\s*اشغالی|حق\s*تعیین\s*سرنوشت\s*ملل|ملل\s*تحت\s*ستم|شوونیسم\s*فارس|پژاک|حزب\s*دموکرات\s*کردستان|جیش\s*العدل/i.test(fullAuthorCorpus)) {
      sepScore += 50;
      sepEvidence.push('ترویج ادبیات ضدتمامیت ارضی («شوونیسم فارس»، «حق تعیین سرنوشت ملل»، یا نام‌های جعلی قومی)');
    }
    if (hasBioWLF && /روژهلات|کوردستان|آذربایجان\s*جنوبی|گونئی|الاحواز|بلوچستان|حق\s*تعیین\s*سرنوشت|ملل\s*تحت\s*ستم|شوونیسم|فدرالیسم|کومله|پژاک|حدکا/i.test(fullAuthorCorpus)) {
      sepScore += 55;
      sepEvidence.push('ترکیب شعار «زن، زندگی، آزادی» با واژگان قومیتی، فدرالیسم و ادبیات ضد تمامیت ارضی');
    }
  }

  // 8. Build Historical Hashtag & Structural Forensics Summary Lines
  const postCount = accountInfo.observedTweetCount || 1;
  const topUserHashtags = Array.from(hashtagFreqMap.values())
    .sort((a, b) => b.count - a.count)
    .slice(0, 8)
    .map(h => `#${h.tag}${Math.ceil(h.count) > 1 ? ` (${Math.ceil(h.count)} بار)` : ''}`);
  const historySummaryBullet = topUserHashtags.length > 0
    ? `• 📊 بررسی تاریخچه (${postCount} پست) و هشتگ‌های پرتکرار اکانت: ${topUserHashtags.join(' ، ')}`
    : `• 📊 بررسی انجام‌شده بر اساس ${postCount} پست و مشخصات پروفایل اکانت.`;

  const extraBullets = [historySummaryBullet, structural.forensicBullet].filter(Boolean);

  // 8b. Idea #3: Fake Monarchist / Anti-Pahlavi Infiltrator Radar (رادار کشف پادشاهی‌خواهان قلابی و نفوذی‌های ضد پهلوی)
  // Triggered when the account wears a Nationalist/Monarchist mask while attacking Prince Reza Pahlavi (without explicit Regime/IRGC martyrdom/missile propaganda, which is handled directly by the Regime Radar below).
  if (
    arzeshiScore < 40 &&
    (
      falseFlagScore >= 45 ||
      isFakeMonarchistAttackingPahlavi ||
      (hasNationalistMaskInBio && (isAttackingPahlavi || quotedAttackOnPahlavi || textStance.antiBarandazTweetCount > 0 || mekScore >= 45))
    )
  ) {
    const hiddenAgenda = mekScore >= 45
      ? 'ترویج خط سازمانی مجاهدین خلق با پوشش ملی‌گرایی'
      : 'تخریب شاهزاده رضا پهلوی و شهبانو فرح، ضدیت با جریان براندازان و هم‌سویی پنهان با منافع امنیتی جمهوری اسلامی';

    return {
      report: {
        identity: `🎭👑 پادشاهی‌خواه/ملی‌گرای قلابی (ضد پهلوی و مخفیانه هم‌سو با ج.ا.)`,
        probability: `۹۲٪ الی ۹۸٪ (بسیار بالا - پروژه نفوذ، عملیات فریب و تفرقه‌افکنی سایبری)`,
        redFlags: [
          ...extraBullets,
          '• 🎭 تناقض هویتی (نقاب پادشاهی/ملی): استفاده ابزاری از نمادهای شیر و خورشید، رضاشاه یا واژگان ملی‌گرایانه برای نفوذ در میان میهن‌پرستان.',
          `• ⚠️ ماموریت و رفتار واقعی در توییت‌ها: ${hiddenAgenda}.`,
          ...uniqueList([...falseFlagEvidence, ...arzeshiEvidence, ...mekEvidence, ...chapiEvidence]).map(e => `• ${e}`)
        ].join('\n'),
        verdict: '🚨 هشدار عملیات فریب (پادشاهی‌خواه قلابی / ضد پهلوی): این اکانت با نقاب پادشاهی‌خواهی یا ملی‌گرایی فعالیت می‌کند اما در متن توییت‌هایش علیه شاهزاده رضا پهلوی و جریان براندازان و در مسیر منافع جمهوری اسلامی گام برمی‌دارد. فریب ظاهر پروفایل یا هشتگ‌ها را نخورید!'
      },
      model: 'False-Flag Radar (رادار کشف پادشاهی‌خواهان قلابی و نفوذی)',
      isMekAlert: false,
      isFalseFlag: true
    };
  }

  // 9. Determine Winning Faction based on Highest Confidence Score
  const scores = [
    { key: 'mek', score: mekScore },
    { key: 'arzeshi', score: arzeshiScore },
    { key: 'separatist', score: sepScore },
    { key: 'pahlavi', score: pahlaviScore },
    { key: 'eslahtalab', score: eslahtalabScore },
    { key: 'chapi', score: chapiScore }
  ].sort((a, b) => b.score - a.score);

  const winner = scores[0];

  if (winner.score >= 35) {
    if (winner.key === 'pahlavi' && pahlaviScore >= 42 && arzeshiScore === 0 && !hasHostileTextAgainstPahlaviOrOpposition) {
      return {
        report: {
          identity: '🦁👑 ملی‌گرا و دموکرات (همراه شاهزاده رضا پهلوی و جنبش ملی)',
          probability: structural.isNumericBotHandle && structural.isNewAccount
            ? '۱۰٪ الی ۲۰٪ (اکانت جدید همراه با جنبش ملی)'
            : '۰٪ الی ۵٪ (بسیار پایین - کاربر واقعی، میهن‌پرست و دموکرات)',
          redFlags: [
            ...extraBullets,
            ...uniqueList(pahlaviEvidence).map(e => `• ${e}`),
            '• مرزبندی قاطع با رژیم جمهوری اسلامی، فرقه رجوی، تجزیه‌طلبان و سایبری‌های ضد پهلوی.'
          ].join('\n'),
          verdict: '👑 کاربر میهن‌پرست، دموکرات و همراه شاهزاده رضا پهلوی؛ بر اساس محتوای متن پست‌ها، گراف تعاملات و هشتگ‌ها، مواضع ایشان در مسیر آزادی میهن، حفظ تمامیت ارضی و پادشاهی مشروطه/دموکراسی است.'
        },
        model: 'Nationalist Radar (رادار ملی‌گرایان دموکرات و همراه پهلوی)',
        isMekAlert: false
      };
    }

    if (winner.key === 'mek' && mekScore >= 50) {
      return {
        report: getMekProxyReport([...extraBullets.map(b => b.replace(/^•\s*/, '')), ...uniqueList(mekEvidence)].join(' | ')),
        model: 'MEK Cult Radar (رادار ضد فرقه مجاهدین خلق)',
        isMekAlert: true
      };
    }

    if (winner.key === 'arzeshi' && arzeshiScore >= 40) {
      const maskNote = hasNationalistMaskInBio
        ? ['• 🎭 پوشش سایبری با نقاب میهن‌پرستی/ملی‌گرایی: استفاده از عناوین ظاهراً ملی (مانند «میهن‌پرست» یا «ایران») در بیوگرافی برای پوشش فعالیت سایبری حکومتی و تخریب شاهزاده رضا پهلوی و جریان براندازی.']
        : [];
      return {
        report: {
          identity: '🔴 حامی جمهوری اسلامی (ارزشی و اصولگرا / سایبری حکومتی)',
          probability: `${Math.max(85, structural.botScore)}٪ الی ۹۵٪ (بسیار بالا - حامی رژیم و پروپاگاندای حکومتی)`,
          redFlags: [
            ...extraBullets,
            ...maskNote,
            ...uniqueList(arzeshiEvidence).map(e => `• ${e}`)
          ].join('\n'),
          verdict: '⛔ مدافع و مروج جمهوری اسلامی (ارزشی / سایبری حکومتی)؛ بر اساس محتوای متن توییت‌ها، این اکانت با وجود ظاهر میهن‌پرستانه یا موج‌سواری روی هشتگ #رضا_پهلوی، در جبهه رژیم و در حال تخریب شاهزاده رضا پهلوی و جریان براندازان فعالیت می‌کند.'
        },
        model: 'Regime Radar (رادار ارزشی و حامیان حکومت)',
        isMekAlert: false
      };
    }

    if (winner.key === 'separatist' && sepScore >= 40) {
      return {
        report: {
          identity: '🏴 جریان تجزیه‌طلب و قوم‌گرا (مخالف تمامیت ارضی ایران)',
          probability: `${Math.max(80, structural.botScore)}٪ الی ۹۵٪ (بالا - تفرقه‌افکنی قومی و واگرایی سرزمینی)`,
          redFlags: [
            ...extraBullets,
            ...sepEvidence.map(e => `• ${e}`)
          ].join('\n'),
          verdict: '🚨 هشدار امنیتی و ملی: این اکانت مروج تفکرات تجزیه‌طلبانه و تخریب تمامیت ارضی ایران است.'
        },
        model: 'Separatist Radar (رادار ضد تجزیه‌طلبی و تمامیت ارضی)',
        isMekAlert: false
      };
    }

    if (winner.key === 'eslahtalab' && eslahtalabScore >= 35) {
      return {
        report: {
          identity: '🟡 حامی رژیم (اصلاح‌طلب و استمرارطلب درون‌ساختاری)',
          probability: '۷۰٪ الی ۸۵٪ (استمرارطلب / حفظ نظام)',
          redFlags: [
            ...extraBullets,
            ...eslahtalabEvidence.map(e => `• ${e}`)
          ].join('\n'),
          verdict: '⚠️ استمرارطلب و مدافع حفظ نظام؛ فعالیت‌های او در جهت بقای ساختار جمهوری اسلامی ارزیابی می‌شود.'
        },
        model: 'Reformist Radar (رادار استمرارطلبان و اصلاحات)',
        isMekAlert: false
      };
    }

    if (winner.key === 'chapi' && chapiScore >= 35) {
      return {
        report: {
          identity: '🟣 جریان چپ / چپول (جمهوری‌خواه چپ و مخالف پادشاهی)',
          probability: '۳۰٪ الی ۵۰٪ (کنشگر طیف چپ / ۵۷ی)',
          redFlags: [
            ...extraBullets,
            ...chapiEvidence.map(e => `• ${e}`)
          ].join('\n'),
          verdict: '🟣 کنشگر طیف چپ و مخالف پادشاهی؛ مواضع او در چارچوب جریان‌های چپ و جمهوری‌خواه ۵۷ی است و همراه پادشاهی‌خواهان نیست.'
        },
        model: 'Leftist Radar (رادار جریان چپ و ۵۷ی)',
        isMekAlert: false
      };
    }
  }

  // 10. Local Forensic Fallback Mode (Used when AI API is unavailable, rate-limited, or restricted)
  if (options && options.allowFallback) {
    if (winner.score >= 15) {
      if (winner.key === 'pahlavi' && arzeshiScore === 0 && !hasHostileTextAgainstPahlaviOrOpposition) {
        return {
          report: {
            identity: '🦁👑 ملی‌گرا و دموکرات (همراه شاهزاده رضا پهلوی و جنبش ملی)',
            probability: '۰٪ الی ۱۰٪ (پایین - کاربر واقعی و همراه جنبش ملی)',
            redFlags: [
              ...extraBullets,
              ...uniqueList(pahlaviEvidence).map(e => `• ${e}`)
            ].join('\n'),
            verdict: '👑 کاربر میهن‌پرست و همراه جنبش ملی ایران.'
          },
          model: 'Nationalist Radar (رادار ملی‌گرایان دموکرات و همراه پهلوی)',
          isMekAlert: false
        };
      }
      if (winner.key === 'mek' && mekScore >= 25) {
        return {
          report: getMekProxyReport([...extraBullets.map(b => b.replace(/^•\s*/, '')), ...uniqueList(mekEvidence)].join(' | ')),
          model: 'MEK Cult Radar (رادار ضد فرقه مجاهدین خلق)',
          isMekAlert: true
        };
      }
      if (winner.key === 'arzeshi') {
        return {
          report: {
            identity: '🔴 حامی جمهوری اسلامی (ارزشی و اصولگرا / سایبری حکومتی)',
            probability: `${Math.max(75, structural.botScore)}٪ الی ۹۰٪ (حامی رژیم)`,
            redFlags: [
              ...extraBullets,
              ...uniqueList(arzeshiEvidence).map(e => `• ${e}`)
            ].join('\n'),
            verdict: '⛔ هم‌سو با مواضع و ادبیات جمهوری اسلامی و مخالف جریان براندازی.'
          },
          model: 'Regime Radar (رادار ارزشی و حامیان حکومت)',
          isMekAlert: false
        };
      }
      if (winner.key === 'separatist') {
        return {
          report: {
            identity: '🏴 جریان تجزیه‌طلب و قوم‌گرا (مخالف تمامیت ارضی ایران)',
            probability: `${Math.max(75, structural.botScore)}٪ الی ۹۰٪ (تفرقه‌افکنی قومی)`,
            redFlags: [
              ...extraBullets,
              ...sepEvidence.map(e => `• ${e}`)
            ].join('\n'),
            verdict: '🚨 هشدار امنیتی و ملی: دارای نشانه‌های قوم‌گرایی افراطی و واگرایی سرزمینی.'
          },
          model: 'Separatist Radar (رادار ضد تجزیه‌طلبی و تمامیت ارضی)',
          isMekAlert: false
        };
      }
      if (winner.key === 'eslahtalab') {
        return {
          report: {
            identity: '🟡 حامی رژیم (اصلاح‌طلب و استمرارطلب درون‌ساختاری)',
            probability: '۶۵٪ الی ۸۰٪ (استمرارطلب / حفظ نظام)',
            redFlags: [
              ...extraBullets,
              ...eslahtalabEvidence.map(e => `• ${e}`)
            ].join('\n'),
            verdict: '⚠️ هم‌سو با طیف اصلاح‌طلبان و استمرارطلبان.'
          },
          model: 'Reformist Radar (رادار استمرارطلبان و اصلاحات)',
          isMekAlert: false
        };
      }
      if (winner.key === 'chapi') {
        return {
          report: {
            identity: '🟣 جریان چپ / چپول (جمهوری‌خواه چپ و مخالف پادشاهی)',
            probability: '۳۰٪ الی ۵۰٪ (کنشگر طیف چپ / ۵۷ی)',
            redFlags: [
              ...extraBullets,
              ...chapiEvidence.map(e => `• ${e}`)
            ].join('\n'),
            verdict: '🟣 دارای نشانه‌ها و کلیدواژه‌های جریان چپ و ناهمسو با پادشاهی مشروطه.'
          },
          model: 'Leftist Radar (رادار جریان چپ و ۵۷ی)',
          isMekAlert: false
        };
      }
    }

    const isMediaOrAcademicBio = /\b(journalist|reporter|correspondent|writer|author|historian|professor|researcher|scholar|columnist|editor|analyst|fellow|news|media|press)\b|خبرنگار|روزنامه‌نگار|روزنامه\s*نگار|نویسنده|پژوهشگر|تحلیل‌گر|تحلیلگر|مورخ|استاد\s*دانشگاه|سردبیر|رسانه|خبرگزاری/i.test(identityHeaderText);
    if (isMediaOrAcademicBio) {
      return {
        report: {
          identity: '🟢 خبرنگار، نویسنده یا پژوهشگر / رسانه (انسان واقعی)',
          probability: `${Math.min(15, structural.botScore || 5)}٪ (بسیار پایین - هویت رسانه‌ای و پژوهشی مشخص)`,
          redFlags: [
            ...extraBullets,
            bio ? `• 📝 مشخصات بیوگرافی: ${bio.slice(0, 180)}` : '• فعالیت رسانه‌ای، نویسندگی یا پژوهشی در توییتر/اکس.',
            '• عدم مشاهده الگوهای رباتیک، بات‌فارم یا پروپاگاندای سازمان‌یافته سایبری در پست‌های بررسی‌شده.'
          ].join('\n'),
          verdict: '✅ اکانت حقیقی با هویت رسانه‌ای، نویسندگی یا پژوهشی؛ شواهدی از بات بودن یا فعالیت سایبری سازمان‌یافته مشاهده نشد.'
        },
        model: 'X-Ray Local Forensic Engine (موتور کالبدشکافی محلی)',
        isMekAlert: false
      };
    }

    if (structural.botScore >= 55 || (structural.isNumericBotHandle && structural.isNewAccount)) {
      return {
        report: {
          identity: '🟠 حساب مشکوک / الگوی نزدیک به بات یا اکانت سایبری ناشناس',
          probability: `${structural.botScore}٪ (متوسط به بالا - نیازمند احتیاط)`,
          redFlags: [
            ...extraBullets,
            '• الگوی ساختاری اکانت (تاریخ ساخت، ساختار هندل عددی یا نسبت تعاملات) دارای نشانه‌های مشکوک سایبری است.',
            '• فاقد هویت شفاف یا سابقه مشخص در پست‌های بررسی‌شده.'
          ].join('\n'),
          verdict: '⚠️ احتیاط کنید: ساختار این اکانت مشکوک به فعالیت سایبری یا حساب فرعی/ناشناس است.'
        },
        model: 'X-Ray Local Forensic Engine (موتور کالبدشکافی محلی)',
        isMekAlert: false
      };
    }

    return {
      report: {
        identity: '⚪ کاربر عادی / شهروند معمولی (فاقد شواهد سایبری یا سازمانی)',
        probability: `${Math.max(5, Math.min(25, structural.botScore || 10))}٪ (پایین - کاربر عادی و غیرسازمانی)`,
        redFlags: [
          ...extraBullets,
          bio ? `• 📝 بیوگرافی اکانت: ${bio.slice(0, 160)}` : '• فعالیت روزمره و شخصی بدون وابستگی به شبکه‌های سازمان‌یافته سایبری.',
          '• عدم مشاهده هشتگ‌های سازمانی رژیم، فرقه رجوی یا پروپاگاندای هماهنگ سایبری در پست‌های بررسی‌شده.'
        ].join('\n'),
        verdict: '💡 کاربر عادی؛ در پست‌ها و مشخصات بررسی‌شده شواهدی از بات بودن یا وابستگی به ارتش‌های سایبری دیده نشد.'
      },
      model: 'X-Ray Local Forensic Engine (موتور کالبدشکافی محلی)',
      isMekAlert: false
    };
  }

  return null;
}

function getMekReport() {
  return {
    identity: '🔴 ارگان تبلیغاتی و رسانه فرقه تروریستی مجاهدین خلق (MEK / رجوی)',
    probability: '۱۰۰٪ (خطر قطعی - ارگان رسمی فرقه تروریستی مجاهدین خلق / رجوی)',
    redFlags: '• وابسته به شبکه رسانه‌ای و ارگان‌های رسمی سازمان مجاهدین خلق (فرقه تروریستی رجوی / آلبانی).\n• استفاده از عناوین فریبنده مانند «تلویزیون ایران آزادی» یا «سیمای آزادی» برای پنهان کردن ماهیت فرقه‌ای و جنایتکارانه خود.\n• پیشینه تاریک خیانت تاریخی به ایران، همکاری با صدام حسین در جنگ ۸ ساله، و ترور هزاران ایرانی.\n• فعالیت متمرکز سایبری از پایگاه تیرانا (اشرف ۳) با هدف تفرقه‌افکنی و دشمنی با خاندان پهلوی و نمادهای ملی ایران.',
    verdict: '🚨 هشدار جدی: ارگان رسمی فرقه تروریستی، خائن و منفور مجاهدین خلق (رجوی)؛ فوراً بلاک و ریپورت کنید!'
  };
}

function getMekProxyReport(detail = '') {
  return {
    identity: '🔴 سایبری و ترول پوششی فرقه تروریستی مجاهدین خلق (MEK / آلبانی)',
    probability: '۹۵٪ الی ۱۰۰٪ (بسیار بالا - ترول فیک و حساب پوششی سایبری رجوی)',
    redFlags: `• حساب کاربری با رفتار سایبری سازمان‌یافته هماهنگ با قرارگاه اشرف ۳ (آلبانی).\n• شواهد شناسایی‌شده در تاریخچه اکانت: ${detail || 'پمپاژ هشتگ‌ها و کارزارهای پوششی فرقه رجوی'}.\n• مرزبندی و عدم همراهی با آرمان‌های ملی ایران و پرهیز عمدی از نام شاهزاده رضا پهلوی و نمادهای ملی‌گرایانه.`,
    verdict: '🚨 هشدار امنیتی قطعی: ترول پوششی و ارتش سایبری فرقه تروریستی مجاهدین خلق (رجوی)؛ فوراً بلاک و ریپورت کنید!'
  };
}

/**
 * Message listener for extension communication
 */
chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
  const action = request.action || request.type;


  if (action === 'ANALYZE_ACCOUNT') {
    (async () => {
      try {
        const res = await handleAccountAnalysis(request);
        sendResponse(res);
      } catch (err) {
        console.error('[X-Ray SW] Account analysis error:', err);
        sendResponse({
          success: false,
          error: 'INTERNAL_ERROR',
          message: err.message || 'خطا در اسکن اکانت.'
        });
      }
    })();
    return true;
  }

  if (action === 'SET_CUSTOM_ACCOUNT_ALIGNMENT') {
    (async () => {
      try {
        const rawHandleInput = String(request.username || request.handle || '').trim();
        const normHandle = normalizeEntityText(rawHandleInput);
        const cleanRestId = String(request.restId || '').trim();
        if (!normHandle) {
          sendResponse({ success: false, message: 'شناسه اکانت نامعتبر است.' });
          return;
        }
        const customMap = await getCustomAccountsMap();

        if (request.faction === 'clear') {
          delete customMap[normHandle];
          await chrome.storage.local.set({ xrayCustomAccounts: customMap });
          await chrome.storage.sync.set({ xrayCustomAccounts: customMap }).catch(() => {});
          // Also remove from scanned badge cache so it re-evaluates fresh
          try {
            const scannedCache = await getScannedBadgesCache();
            delete scannedCache[normHandle];
            await chrome.storage.local.set({ xrayScannedBadgesCache: scannedCache });
          } catch (e) {}
          sendResponse({ success: true, cleared: true, customAccounts: customMap });
          return;
        }

        const cleanDisplayHandle = rawHandleInput.startsWith('@') ? rawHandleInput : `@${rawHandleInput}`;
        customMap[normHandle] = {
          handle: cleanDisplayHandle,
          displayName: request.displayName || cleanDisplayHandle,
          faction: request.faction,
          restId: cleanRestId || customMap[normHandle]?.restId || '',
          note: request.note || '',
          updatedAt: Date.now()
        };
        await chrome.storage.local.set({ xrayCustomAccounts: customMap });
        await chrome.storage.sync.set({ xrayCustomAccounts: customMap }).catch(() => {});
        await saveScannedBadge(cleanDisplayHandle, request.faction, cleanRestId, request.displayName || cleanDisplayHandle);

        if (cleanRestId) {
          const restReg = await getRestIdRegistry();
          const prev = restReg[cleanRestId] || { restId: cleanRestId, currentHandle: normHandle, previousHandles: [] };
          prev.faction = request.faction;
          prev.updatedAt = Date.now();
          restReg[cleanRestId] = prev;
          await saveRestIdRegistry(restReg);
        }

        const pinnedReport = buildStandardFactionReport(
          request.faction,
          request.displayName || cleanDisplayHandle,
          request.note || `گرایش سیاسی این اکانت (${cleanDisplayHandle}) توسط شما به صورت دائمی در حافظه X-Ray ثبت و قفل شده است.`
        );
        const formattedAnalysis = `🤖 تشخیص هویت اکانت: ${pinnedReport.identity}
📊 احتمال فیک/سایبری/بات بودن: ${pinnedReport.probability}
🚩 سرنخ‌ها و شواهد سازمانی یا رفتاری:
${pinnedReport.redFlags}
💡 حکم و هشدار امنیتی X-Ray: ${pinnedReport.verdict}`;

        sendResponse({
          success: true,
          analysis: formattedAnalysis,
          model: pinnedReport.modelTag,
          faction: request.faction,
          isMekAlert: pinnedReport.isMekAlert,
          isFalseFlag: pinnedReport.isFalseFlag,
          customAccounts: customMap
        });
      } catch (err) {
        sendResponse({ success: false, message: err.message });
      }
    })();
    return true;
  }

  if (action === 'GET_BADGE_DIRECTORY') {
    (async () => {
      try {
        const dir = await buildBadgeDirectoryPayload();
        sendResponse({ success: true, ...dir });
      } catch (err) {
        sendResponse({ success: false, handleMap: {}, restIdMap: {} });
      }
    })();
    return true;
  }

  if (action === 'REGISTER_REST_ID_OBSERVATIONS') {
    (async () => {
      try {
        const items = Array.isArray(request.users) ? request.users : [];
        if (items.length === 0) {
          sendResponse({ success: true, updated: {} });
          return;
        }
        const restReg = await getRestIdRegistry();
        const customMap = await getCustomAccountsMap();
        let changed = false;
        const handleChanges = {};

        for (const u of items) {
          const rId = String(u.restId || '').trim();
          const rawH = String(u.handle || '').replace(/^@/, '').toLowerCase().trim();
          const normH = normalizeEntityText(rawH);
          if (!rId || !rawH) continue;

          let entry = restReg[rId];
          if (!entry) {
            const resolved = resolveHandleFaction(rawH, customMap);
            entry = {
              restId: rId,
              currentHandle: rawH,
              previousHandles: [],
              displayName: u.displayName || '',
              faction: resolved?.faction || '',
              updatedAt: Date.now()
            };
            restReg[rId] = entry;
            changed = true;
          } else {
            if (entry.currentHandle && normalizeEntityText(entry.currentHandle) !== normH) {
              if (!Array.isArray(entry.previousHandles)) entry.previousHandles = [];
              const alreadyRecorded = entry.previousHandles.some(
                ph => normalizeEntityText(ph) === normalizeEntityText(entry.currentHandle)
              );
              if (!alreadyRecorded) {
                entry.previousHandles.push(entry.currentHandle);
              }
              if (!entry.faction) {
                const oldResolved = resolveHandleFaction(entry.currentHandle, customMap);
                if (oldResolved?.faction) entry.faction = oldResolved.faction;
              }
              entry.currentHandle = rawH;
              entry.updatedAt = Date.now();
              changed = true;
            }
            if (u.displayName && u.displayName !== entry.displayName) {
              entry.displayName = u.displayName;
              changed = true;
            }
            if (!entry.faction) {
              const resolved = resolveHandleFaction(rawH, customMap);
              if (resolved?.faction) {
                entry.faction = resolved.faction;
                changed = true;
              }
            }
          }

          if (entry.previousHandles && entry.previousHandles.length > 0) {
            handleChanges[normH] = {
              restId: rId,
              previousHandles: entry.previousHandles,
              faction: entry.faction || ''
            };
          }
        }

        if (changed) {
          await saveRestIdRegistry(restReg);
        }

        sendResponse({ success: true, handleChanges });
      } catch (err) {
        sendResponse({ success: false, message: err.message });
      }
    })();
    return true;
  }

  if (action === 'RECORD_USER_FEEDBACK') {
    (async () => {
      try {
        const rawHandle = String(request.username || request.handle || '').trim();
        const normH = normalizeEntityText(rawHandle);
        const faction = String(request.faction || '').trim();
        const restId = String(request.restId || '').trim();
        if (normH && faction) {
          const customMap = await getCustomAccountsMap();
          const cleanDisplayHandle = rawHandle.startsWith('@') ? rawHandle : `@${rawHandle}`;
          if (!customMap[normH]) {
            customMap[normH] = {
              handle: cleanDisplayHandle,
              displayName: request.displayName || cleanDisplayHandle,
              faction,
              restId,
              note: 'تأییدشده توسط فیدبک کاربر (👍) در X-Ray.',
              updatedAt: Date.now()
            };
            await chrome.storage.local.set({ xrayCustomAccounts: customMap });
            await chrome.storage.sync.set({ xrayCustomAccounts: customMap }).catch(() => {});
          }
          await saveScannedBadge(cleanDisplayHandle, faction, restId, request.displayName || cleanDisplayHandle);
        }
        sendResponse({ success: true });
      } catch (err) {
        sendResponse({ success: false, message: err.message });
      }
    })();
    return true;
  }

  if (action === 'GET_CUSTOM_ACCOUNTS') {
    (async () => {
      try {
        const customMap = await getCustomAccountsMap();
        let builtInCount = 0;
        KNOWN_POLITICAL_ACCOUNTS.forEach(g => { builtInCount += (g.handles || []).length; });
        sendResponse({
          success: true,
          customAccounts: customMap,
          builtInCount
        });
      } catch (err) {
        sendResponse({ success: false, message: err.message, customAccounts: {} });
      }
    })();
    return true;
  }

  if (action === 'IMPORT_CUSTOM_ACCOUNTS') {
    (async () => {
      try {
        const incoming = request.accounts;
        if (!incoming || typeof incoming !== 'object') {
          sendResponse({ success: false, message: 'فرمت فایل JSON نامعتبر است.' });
          return;
        }
        const customMap = await getCustomAccountsMap();
        let importedCount = 0;

        if (Array.isArray(incoming)) {
          for (const item of incoming) {
            const rawH = item.handle || item.username;
            const normH = normalizeEntityText(rawH);
            if (normH && item.faction) {
              customMap[normH] = {
                handle: String(rawH).startsWith('@') ? rawH : `@${rawH}`,
                displayName: item.displayName || rawH,
                faction: item.faction,
                note: item.note || '',
                updatedAt: Date.now()
              };
              importedCount++;
            }
          }
        } else {
          for (const [k, item] of Object.entries(incoming)) {
            const rawH = item?.handle || item?.username || k;
            const normH = normalizeEntityText(rawH);
            const faction = typeof item === 'string' ? item : item?.faction;
            if (normH && faction) {
              customMap[normH] = {
                handle: String(rawH).startsWith('@') ? rawH : `@${rawH}`,
                displayName: item?.displayName || rawH,
                faction,
                note: item?.note || '',
                updatedAt: Date.now()
              };
              importedCount++;
            }
          }
        }

        await chrome.storage.local.set({ xrayCustomAccounts: customMap });
        await chrome.storage.sync.set({ xrayCustomAccounts: customMap }).catch(() => {});
        sendResponse({
          success: true,
          importedCount,
          customAccounts: customMap
        });
      } catch (err) {
        sendResponse({ success: false, message: err.message });
      }
    })();
    return true;
  }

  if (action === 'GET_MODELS') {
    (async () => {
      try {
        const res = await fetchAvailableModels(request.apiKey);
        sendResponse(res);
      } catch (err) {
        sendResponse({ success: false, message: err.message, models: [] });
      }
    })();
    return true;
  }

  if (action === 'TEST_API_KEY') {
    (async () => {
      try {
        const res = await handleApiKeyTest(request.apiKey, request.model);
        sendResponse(res);
      } catch (err) {
        sendResponse({
          success: false,
          message: err.message || 'Error testing connection.'
        });
      }
    })();
    return true;
  }

  return false;
});

/**
 * Fetches available chat models from Groq for the given API key
 */
async function fetchAvailableModels(keyToUse) {
  let key = (keyToUse || '').trim();
  if (!key) {
    const storage = await chrome.storage.sync.get(['groqApiKey', 'apiKey']);
    key = (storage.groqApiKey || storage.apiKey || '').trim();
  }

  if (!key) {
    return { success: false, message: 'No API key provided.', models: [] };
  }

  try {
    const res = await fetch(GROQ_MODELS_URL, {
      method: 'GET',
      headers: { 'Authorization': `Bearer ${key}` }
    });

    if (!res.ok) {
      return { success: false, message: `HTTP ${res.status}`, models: [] };
    }

    const data = await res.json();
    const modelItems = Array.isArray(data?.data) ? data.data : [];
    const activeIds = modelItems.filter(m => m && m.active !== false).map(m => m.id);

    // Filter out specialized, non-chat, or unsuited models
    const filteredModels = activeIds.filter(isSupportedChatModel);
    const sortedModels = sortModelsByRanking(filteredModels);

    return { success: true, models: sortedModels };
  } catch (err) {
    return { success: false, message: err.message, models: [] };
  }
}



/**
 * Validates a Groq API key by querying models endpoint and verifying chat access
 */
async function handleApiKeyTest(keyToTest, preferredModel) {
  let key = (keyToTest || '').trim();
  if (!key) {
    const storage = await chrome.storage.sync.get(['groqApiKey', 'apiKey']);
    key = (storage.groqApiKey || storage.apiKey || '').trim();
  }
  if (!key) {
    return { success: false, message: 'No API key provided.' };
  }

  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), 12000);

  try {
    // 1. First test key validity via /models endpoint (no inference tokens consumed)
    const modelsResponse = await fetch(GROQ_MODELS_URL, {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${key}`
      },
      signal: controller.signal
    });

    clearTimeout(timeoutId);

    if (modelsResponse.status === 401) {
      return { success: false, message: 'Invalid API key (401 Unauthorized).' };
    }

    if (!modelsResponse.ok) {
      const err = await modelsResponse.json().catch(() => null);
      return {
        success: false,
        message: err?.error?.message || `HTTP ${modelsResponse.status} connection error.`
      };
    }

    const modelsData = await modelsResponse.json();
    const modelItems = Array.isArray(modelsData?.data) ? modelsData.data : [];
    const activeIds = modelItems.filter(m => m && m.active !== false).map(m => m.id);

    // Filter out specialized or unsuited models
    const availableChatModels = activeIds.filter(isSupportedChatModel);
    const sortedChatModels = sortModelsByRanking(availableChatModels);

    // Filter out unsuited models from preferred if passed
    const cleanPreferred = (preferredModel && isSupportedChatModel(preferredModel)) ? preferredModel : null;

    const PRIORITY_CANDIDATES = [
      cleanPreferred,
      DEFAULT_MODEL,
      'qwen/qwen3.8-27b',
      'qwen/qwen3.6-27b',
      'qwen-2.5-32b',
      'deepseek-r1-distill-llama-70b',
      FALLBACK_MODEL,
      'llama-3.1-8b-instant',
      'llama-3.1-70b-versatile',
      'mixtral-8x7b-32768',
      'gemma2-9b-it',
      'openai/gpt-oss-120b',
      'openai/gpt-oss-20b'
    ].filter(Boolean);

    let modelToTest = PRIORITY_CANDIDATES.find(m => sortedChatModels.includes(m)) || sortedChatModels[0] || FALLBACK_MODEL;

    // 2. Perform a lightweight ping completion
    const pingController = new AbortController();
    const pingTimeout = setTimeout(() => pingController.abort(), 10000);

    const pingResponse = await fetch(GROQ_API_URL, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${key}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        model: modelToTest,
        max_tokens: 5,
        messages: [{ role: 'user', content: 'Ping' }]
      }),
      signal: pingController.signal
    });

    clearTimeout(pingTimeout);

    if (pingResponse.ok) {
      // Save working model
      await chrome.storage.sync.set({ selectedModel: modelToTest });
      return {
        success: true,
        message: `API key is valid! Connected to model: ${modelToTest}`,
        selectedModel: modelToTest,
        availableModels: sortedChatModels
      };
    }

    // If preferred model had access issues, try fallback to FALLBACK_MODEL
    if (modelToTest !== FALLBACK_MODEL) {
      const fallbackResponse = await fetch(GROQ_API_URL, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${key}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          model: FALLBACK_MODEL,
          max_tokens: 5,
          messages: [{ role: 'user', content: 'Ping' }]
        })
      });

      if (fallbackResponse.ok) {
        await chrome.storage.sync.set({ selectedModel: FALLBACK_MODEL });
        return {
          success: true,
          message: `Key valid! Model ${modelToTest} is unavailable for this key; fallback model ${FALLBACK_MODEL} was activated.`,
          selectedModel: FALLBACK_MODEL,
          availableModels: sortedChatModels
        };
      }
    }

    const pingErr = await pingResponse.json().catch(() => null);
    return {
      success: false,
      message: pingErr?.error?.message || `HTTP ${pingResponse.status} during model test.`
    };
  } catch (err) {
    clearTimeout(timeoutId);
    return {
      success: false,
      message: err.name === 'AbortError' ? 'Connection test timed out.' : `Network error: ${err.message}`
    };
  }
}

/**
 * Finalizes an account analysis response by caching its faction badge and attaching permanent restId history
 */
async function finalizeAnalysisResult(resObj, accountInfo) {
  if (!resObj || !resObj.success || !accountInfo) return resObj;
  const rawHandle = String(accountInfo.username || '').trim();
  const normH = normalizeEntityText(rawHandle);
  const cleanRestId = String(accountInfo.restId || resObj.restId || '').trim();
  const inferredFaction = resObj.faction || inferFactionFromAnalysisText(resObj.analysis, resObj.isMekAlert, resObj.isFalseFlag);

  let previousHandles = Array.isArray(resObj.previousHandles) ? resObj.previousHandles : [];

  try {
    if (cleanRestId) {
      const restReg = await getRestIdRegistry();
      const entry = restReg[cleanRestId];
      if (entry) {
        if (Array.isArray(entry.previousHandles)) {
          previousHandles = entry.previousHandles.filter(h => normalizeEntityText(h) !== normH);
        }
        if (entry.faction !== (inferredFaction || '')) {
          entry.faction = inferredFaction || '';
          await saveRestIdRegistry(restReg);
        }
      }
    }
    if (rawHandle && inferredFaction) {
      await saveScannedBadge(rawHandle, inferredFaction, cleanRestId, accountInfo.displayName || rawHandle);
    }
  } catch (e) {}

  return {
    ...resObj,
    faction: inferredFaction || '',
    restId: cleanRestId,
    previousHandles
  };
}

/**
 * Performs forensic analysis on an account to detect bots, cyber-army, and false-flag accounts
 */
async function handleAccountAnalysis({ accountInfo }) {
  if (!accountInfo) {
    return { success: false, error: 'NO_DATA', message: 'اطلاعاتی از اکانت دریافت نشد.' };
  }

  // 1. Lookup in User-Pinned & Known Political Accounts Registry (Always takes highest precedence!)
  const pinnedOrKnown = await matchPinnedOrKnownPoliticalAccount(
    accountInfo.username,
    accountInfo.displayName,
    accountInfo.restId
  );
  if (pinnedOrKnown) {
    const formattedAnalysis = `🤖 تشخیص هویت اکانت: ${pinnedOrKnown.identity}
📊 احتمال فیک/سایبری/بات بودن: ${pinnedOrKnown.probability}
🚩 سرنخ‌ها و شواهد سازمانی یا رفتاری:
${pinnedOrKnown.redFlags}
💡 حکم و هشدار امنیتی X-Ray: ${pinnedOrKnown.verdict}`;

    return finalizeAnalysisResult({
      success: true,
      analysis: formattedAnalysis,
      model: pinnedOrKnown.modelTag || pinnedOrKnown.model || 'X-Ray Known Accounts Registry (بانک اکانت‌های شناخته‌شده)',
      isMekAlert: Boolean(pinnedOrKnown.isMekAlert),
      isFalseFlag: Boolean(pinnedOrKnown.isFalseFlag),
      previousHandles: pinnedOrKnown.previousHandles || [],
      restId: pinnedOrKnown.restId || accountInfo.restId || ''
    }, accountInfo);
  }

  // 2. Instant Verification for Recognized Authentic Public Figures & Media (Prince Reza Pahlavi, Press Office, Empress Farah, Diplomats, etc.)
  const known = matchKnownEntity(accountInfo.username, accountInfo.displayName, accountInfo.bio);
  if (known) {
    const isGovEntity = Boolean(
      (known.modelTag && known.modelTag.includes('Government')) ||
      (known.identity && known.identity.includes('دولتی'))
    );
    const formattedAnalysis = `🤖 تشخیص هویت اکانت: ${known.identity}
📊 احتمال فیک/سایبری/بات بودن: ${known.probability}
🚩 سرنخ‌ها و شواهد سازمانی یا رفتاری:
${known.redFlags}
💡 حکم و هشدار امنیتی X-Ray: ${known.verdict}`;

    return finalizeAnalysisResult({
      success: true,
      analysis: formattedAnalysis,
      model: known.modelTag || 'Verified Matrix (مرجع تایید چهره‌ها و رسانه‌ها)',
      isGovernment: isGovEntity,
      faction: isGovEntity ? 'government' : (known.faction || '')
    }, accountInfo);
  }

  // 3. Enrich Account with Historical Timeline & Older Post Hashtags
  const enrichedAccountInfo = await enrichAccountWithHistoricalTimeline(accountInfo);
  const customMap = await getCustomAccountsMap();

  // 4. Multi-Signal Weighted Political Scoring Engine (with Sentiment, Interaction Graph & False-Flag Guards)
  const weightedAlignment = evaluateAccountAlignment(enrichedAccountInfo, customMap);
  if (weightedAlignment) {
    const rep = weightedAlignment.report || weightedAlignment;
    const formattedAnalysis = `🤖 تشخیص هویت اکانت: ${rep.identity}
📊 احتمال فیک/سایبری/بات بودن: ${rep.probability}
🚩 سرنخ‌ها و شواهد سازمانی یا رفتاری:
${rep.redFlags}
💡 حکم و هشدار امنیتی X-Ray: ${rep.verdict}`;

    return finalizeAnalysisResult({
      success: true,
      analysis: formattedAnalysis,
      model: weightedAlignment.model,
      isGovernment: Boolean(weightedAlignment.isGovernment),
      isGoldBadge: Boolean(weightedAlignment.isGoldBadge),
      faction: weightedAlignment.isGovernment ? 'government' : (weightedAlignment.isGoldBadge ? 'organization' : ''),
      isMekAlert: Boolean(weightedAlignment.isMekAlert),
      isFalseFlag: Boolean(weightedAlignment.isFalseFlag),
      harvestedData: enrichedAccountInfo.__harvestedData || null
    }, enrichedAccountInfo);
  }

  const storage = await chrome.storage.sync.get(['groqApiKey', 'apiKey', 'selectedModel']);
  const localData = await chrome.storage.local.get(['cachedModels']).catch(() => ({}));
  const apiKey = (storage.groqApiKey || storage.apiKey || '').trim();

  if (!apiKey) {
    const fallbackAlignment = evaluateAccountAlignment(enrichedAccountInfo, customMap, { allowFallback: true });
    if (fallbackAlignment) {
      const rep = fallbackAlignment.report || fallbackAlignment;
      const formattedAnalysis = `🤖 تشخیص هویت اکانت: ${rep.identity}
📊 احتمال فیک/سایبری/بات بودن: ${rep.probability}
🚩 سرنخ‌ها و شواهد سازمانی یا رفتاری:
${rep.redFlags}
💡 حکم و هشدار امنیتی X-Ray: ${rep.verdict}`;
      return finalizeAnalysisResult({
        success: true,
        analysis: formattedAnalysis,
        model: fallbackAlignment.model,
        isMekAlert: Boolean(fallbackAlignment.isMekAlert),
        isFalseFlag: Boolean(fallbackAlignment.isFalseFlag),
        harvestedData: enrichedAccountInfo.__harvestedData || null
      }, enrichedAccountInfo);
    }
    return {
      success: false,
      error: 'NO_API_KEY',
      message: 'لطفاً ابتدا کلید Groq API خود را در آیکون X-Ray وارد کنید.'
    };
  }

  let modelToUse = (storage.selectedModel || DEFAULT_MODEL).trim();
  if (!isSupportedChatModel(modelToUse)) {
    modelToUse = DEFAULT_MODEL;
  }

  const isStrictEnrichedGov = Boolean(
    !isIranianRegimeOfficial(enrichedAccountInfo) &&
    (
      Boolean(enrichedAccountInfo.isGreyBadge) ||
      enrichedAccountInfo.verifiedType === 'Government' ||
      /تیک خاکستری|حساب رسمی دولتی/i.test(enrichedAccountInfo.governmentLabel || '')
    )
  );

  const isStrictEnrichedGold = Boolean(
    !isStrictEnrichedGov &&
    !isIranianRegimeOfficial(enrichedAccountInfo) &&
    (
      Boolean(enrichedAccountInfo.isGoldBadge) ||
      enrichedAccountInfo.verifiedType === 'Business' ||
      /تیک طلایی|سازمان رسمی|شرکت ثبت‌شده|verified organization/i.test(enrichedAccountInfo.governmentLabel || '')
    )
  );

  let verificationText = 'عادی';
  if (isStrictEnrichedGov) {
    verificationText = '🏛️ نشان رسمی خاکستری دولتی خارجی (Grey Checkmark - حساب رسمی دولتها یا نهادهای بین‌المللی)';
  } else if (isStrictEnrichedGold) {
    verificationText = '🏢 نشان رسمی طلایی سازمان‌ها و شرکت‌های ثبت‌شده (Gold Checkmark - Verified Organization)';
  } else if (enrichedAccountInfo.isVerified) {
    verificationText = isIranianRegimeOfficial(enrichedAccountInfo)
      ? '🔷 تیک آبی تجاری/عادی (فاقد نشان خاکستری دولتی یا طلایی سازمانی)'
      : '✅ تایید شده (دارای نشان رسمی Verified / تیک آبی)';
  }
  const govLabelText = ((isStrictEnrichedGov || isStrictEnrichedGold) && enrichedAccountInfo.governmentLabel)
    ? `\n- برچسب رسمی توییتر/اکس: ${enrichedAccountInfo.governmentLabel}`
    : '';

  const handlesText = (enrichedAccountInfo.referencedHandles && enrichedAccountInfo.referencedHandles.length > 0)
    ? `\n- اکانت‌های نقل‌شده، منشن‌شده یا ریتوییت‌شده در توییت‌ها: ${enrichedAccountInfo.referencedHandles.map(h => '@' + h).join(', ')}`
    : '';
  const linksText = (enrichedAccountInfo.links && enrichedAccountInfo.links.length > 0)
    ? `\n- لینک‌ها یا وب‌سایت‌های ارجاع‌داده‌شده: ${enrichedAccountInfo.links.slice(0, 5).join(' | ')}`
    : '';
  const userUrlText = enrichedAccountInfo.userUrl
    ? `\n- وب‌سایت موجود در مشخصات پروفایل: ${enrichedAccountInfo.userUrl}`
    : '';
  const hashtagsSummaryText = (enrichedAccountInfo.authorHashtags && enrichedAccountInfo.authorHashtags.length > 0)
    ? `\n- هشتگ‌های استخراج‌شده از پست‌های قدیم و جدید خود این اکانت: ${enrichedAccountInfo.authorHashtags.slice(0, 25).map(h => typeof h === 'string' ? h : `#${h.tag}${h.count > 1 ? ` (${Math.ceil(h.count)} بار)` : ''}`).join(' ، ')}`
    : '';
  const historyMetaText = enrichedAccountInfo.observedTweetCount
    ? `\n- تعداد پست‌های قدیمی و جدید بررسی‌شده در حافظه و آرشیو: ${enrichedAccountInfo.observedTweetCount} پست`
    : '';

  // Compute pre-scan text stance signals so the AI never gets fooled by hijacked hashtags (#رضا_پهلوی)
  const promptOwnText = enrichedAccountInfo.authorOwnTextOnly || enrichedAccountInfo.currentTweet || enrichedAccountInfo.tweetsSample || '';
  const promptHeaderText = `${enrichedAccountInfo.username || ''} ${enrichedAccountInfo.displayName || ''} ${enrichedAccountInfo.bio || ''}`;
  const promptTagMap = buildAuthorHashtagFrequencyMap(`${promptHeaderText}\n${promptOwnText}`, enrichedAccountInfo.authorHashtags || []);
  const promptStance = analyzeTweetTextStance(enrichedAccountInfo, promptOwnText, promptHeaderText, promptTagMap);
  const stanceWarnings = [
    ...(promptStance.isHijackingPahlaviHashtags
      ? [`⚠️ هشدار موج‌سواری سایبری روی هشتگ (Hashtag Hijacking): این اکانت از هشتگ #رضا_پهلوی استفاده کرده اما متن توییت‌هایش فاقد هرگونه ستایش از شاهزاده است و برعکس، علیه رضا پهلوی و علیه جریان براندازان است!`]
      : []),
    ...promptStance.antiPahlaviReasons,
    ...promptStance.antiBarandazReasons,
    ...promptStance.regimeIntelReasons
  ];
  const stancePreScanText = stanceWarnings.length > 0
    ? `\n- 🔍 یافته‌های حیاتی کالبدشکافی محتوای متن توییت‌ها (اولویت مطلق با متن توییت است نه صرفاً نام هشتگ):\n  * ${stanceWarnings.join('\n  * ')}`
    : '';

  const userPrompt = `اطلاعات و مشخصات اکانت جهت جریان‌شناسی سیاسی و تفکیک هویت در توییتر فارسی:
- نام نمایشی: ${enrichedAccountInfo.displayName || 'نامشخص'}
- شناسه کاربری (Handle): ${enrichedAccountInfo.username || 'نامشخص'}
- نشان رسمی (Verified): ${verificationText}${govLabelText}
- بیوگرافی (Bio): ${enrichedAccountInfo.bio || 'ندارد یا استخراج نشده'}${userUrlText}
- مشخصات پروفایل و آمار: ${enrichedAccountInfo.metadata || 'در دسترس نیست'}${historyMetaText}${hashtagsSummaryText}${handlesText}${linksText}${stancePreScanText}
- نمونه توییت‌های قدیم و جدید خود این اکانت (به‌همراه هشتگ‌های استخراج‌شده):
«««
${(enrichedAccountInfo.tweetsSample || enrichedAccountInfo.currentTweet || 'توییتی در دسترس نیست').slice(0, 4500)}
»»»

دستورات فوق‌العاده حیاتی و خط قرمزهای تخطی‌ناپذیر ارزیابی:
۰. خط قرمز مطلق در ادبیات نگارش (عدم استفاده از واژه «شهید» برای مبارزان و ملی‌گرایان):
   - برای مبارزان، ملی‌گرایان، پادشاهی‌خواهان، جان‌باختگان راه آزادی و جان‌فداهای میهن هرگز و تحت هیچ شرایطی از کلمه «شهید»، «شهدا» یا «شهادت» (که ادبیات تحمیلی و تبلیغاتی رژیم است) استفاده نکن!
   - منحصراً از واژگان اصیل و ملی مانند «جان‌فدا»، «جاویدنام»، «جان‌باخته راه آزادی» یا «فرزندان دلیر ایران» استفاده کن.
   - واژه «شهید» تنها در مقام کشف و افشای سایبری‌ها و ماموران رژیم (استفاده آن‌ها از این واژه برای کشته‌های سپاه و بسیج) به عنوان سرنخ وابستگی به حکومت به کار می‌رود.
۱. پادشاهی‌خواه و ملی‌گرا (حامی پهلوی و جنبش ملی) و قانون طلایی اولویت متن بر هشتگ:
   - استفاده از هشتگ‌ها یا نمادهای شاخص در صورت همراهی متن توییت‌ها: #جاویدشاه، #KingRezaPahlavi، #رضاشاه_دوم، #ایران_سرای_شاهان، #انقلاب_شیروخورشید، #پهلوی_امید_ملت، نماد شیر و خورشید یا تاج در نام/بیو، و دفاع واقعی در متن توییت‌ها از شاهزاده رضا پهلوی و ایران‌گرایی.
   - هشدار بسیار مهم درباره موج‌سواری سایبری روی هشتگ #رضا_پهلوی: اکانت‌های سایبری رژیم، پایداری‌چی‌ها و نفوذی‌های ضدبرانداز به وفور هشتگ #رضا_پهلوی یا #پهلوی را پای توییت‌های خود می‌زنند تا پست‌های تخریبی‌شان علیه شاهزاده رضا پهلوی و علیه «براندازها / جریان برانداز / اپوزیسیون» دیده شود! هرگز صرفاً با دیدن هشتگ #رضا_پهلوی یا عبارت «میهن‌پرست» در بیو، اکانتی را پادشاهی‌خواه تشخیص نده؛ حتماً متن جملات توییت‌ها را بخوان! اگر متن توییت‌ها علیه رضا پهلوی یا علیه براندازهاست، اکانت ۱۰۰٪ ضد پهلوی و سایبری رژیم (دسته ۳-الف) است!
   - قانون ضد خطا (Anti-False-Positive): اکانت‌های ملی‌گرا و پادشاهی‌خواه ممکن است در برخی پست‌ها در مورد «مجاهدین خلق / فرقه رجوی» یا «چپول‌ها / ۵۷ی‌ها» بنویسند تا آن‌ها را نقد، افشا یا مسخره کنند! هرگز به صرف دیده شدن کلمه «مجاهدین» یا «رجوی» یا «چپ» در متن توییت یک کاربر، او را مجاهد یا چپی تشخیص نده! حتماً جهت جمله (نقد در برابر ستایش) را بررسی کن.
۲. چپی‌ها و چپول‌ها (جریان‌های چپ، فمینیست‌های رادیکال و جمهوری‌خواه ۵۷ی):
   - اکانت‌هایی که در بیوگرافی خود شعار «زن، زندگی، آزادی» (یا معادل‌های انگلیسی Woman Life Freedom یا کردی Jin Jiyan Azadi / ژن ژیان ئازادی) یا عناوین فمینیست/کوئیر/عدالت انتقالی دارند و همزمان فاقد نمادهای پادشاهی (🦁، ☀️، 👑، #جاویدشاه، #پهلوی) هستند، یا به شاهزاده رضا پهلوی، پادشاهی و تاریخ ملی ایران حمله می‌کنند.
   - استفاده از هشتگ‌ها و شعارهای اختصاصی: #چپ، #سوسیالیسم، #کارگر، #جمهوری_دموکراتیک، #نه_شاه_نه_شیخ، #عدالت_اجتماعی، #امپریالیسم، #فمینیسم، #فمینیست، ستم مضاعف، و حمله به پادشاهی پهلوی، تاریخ معاصر یا مواضع ساواک.
   - هشدار ضد خطا: کلمات عمومی اعتراضی مثل «آزادی»، «انقلاب»، «مهسا امینی»، «مرگ بر دیکتاتور» یا «زندانی سیاسی» را به‌تنهایی به عنوان مدرک چپ بودن حساب نکن، اما وجود زن‌زندگی‌آزادی در بیو در غیاب نمادهای ملی‌گرایی نشانه چپول‌ها یا واگرایان است.
۳. جمهوری اسلامی (حامیان حکومت ملاها):
   ۳-الف. ارزشی و اصولگرا (ولایی، پایداری‌چی، سایبری و ارگان‌های رسمی رژیم):
   - قانون قطعی و تخطی‌ناپذیر سفارت‌خانه‌ها و نهادهای رسمی جمهوری اسلامی:
     کلیه سفارت‌خانه‌ها، کنسولگری‌ها، وزارت امور خارجه (mfa.ir)، نمایندگی‌های دیپلماتیک، ارگان‌ها و خبرگزاری‌های وابسته به «جمهوری اسلامی ایران» (مانند سفارتخانه‌های ایران با نام Iran Embassy یا دامنه‌های mfa.ir)، ۱۰۰٪ و بدون استثنا جزو دسته «۳-الف. ارگان رسمی حکومت جمهوری اسلامی (ارزشی و حکومتی)» هستند! آن‌ها به هیچ عنوان نباید در دسته ۶ یا ۷ یا دولتی خنثی قرار گیرند!
   - ستایش از «ولی فقیه / ولایت فقیه»، خامنه‌ای، سپاه، سران، مقامات یا دیپلمات‌های رژیم، یا استفاده از نشان رسمی حکومت جمهوری اسلامی «☫» در نام نمایشی/بیوگرافی.
   - استفاده از ادبیات رسمی حکومت برای نیروهای نظامی/انتظامی رژیم («شهید ... به شهادت رسید»، «شهدای امنیت»)، کلیدواژه‌های امنیتی مثل «شبکه نفوذ / مبارزه با شبکه نفوذ»، #سرطان_اصلاحات، یا هشتگ‌ها و القاب تخریبی سایبری علیه شاهزاده رضا پهلوی و براندازان (#رضا_دادول، ربع پهلوی، شازده، #سلطنت_طلبان، حمله به «براندازها / جریان برانداز / اپوزیسیون» حتی با موج‌سواری روی هشتگ #رضا_پهلوی).
   - هشدار سایبری‌های «ایران‌شهری / باستان‌گرای حکومتی»: اگر اکانتی در نام یا بیوگرافی خود از عناوین ظاهراً ملی مثل «یک ایرانی میهن پرست»، «Empire Of Iran» یا «از تبار کوروش» استفاده کرده، اما در توییت‌هایش به رضا پهلوی و براندازها حمله می‌کند، از هشتگ‌هایی مثل #رضا_دادول و #سرطان_اصلاحات استفاده می‌کند یا ادبیات امنیتی «شبکه نفوذ» دارد، قطعاً جزو «۳-الف. ارزشی و اصولگرا (سایبری حکومتی)» است!
   - نکته مهم: اکانت‌های ولایی افراطی و پایداری‌چی که از موضع دفاع از «ولی فقیه» به اصلاح‌طلبان، پزشکیان، ظریف، خاتمی، روحانی یا لاریجانی («وفاقی‌ها / کودتاگران / سرطان اصلاحات») حمله می‌کنند، قطعاً جزو «۳-الف. ارزشی و اصولگرا (حامی رژیم)» هستند!
   - هشتگ‌های شاخص: #لبیک_یا_خامنه_ای، #ایران_مقتدر، #خاندان_خیانت، #پهلوی_خائن، #وحوش_پهلوی، #رضا_دادول، #سرطان_اصلاحات، #نحن_المنتقمون
   ۳-ب. اصلاح‌طلب و استمرارطلب:
   - هشتگ‌های شاخص: #اصلاح_طلبان، #جبهه_اصلاحات، #آذر_منصوری، #پزشکیان، #خاتمی، #ظریف، #مشارکت
۴. مجاهدین خلق (MEK / فرقه رجوی):
   - فقط در صورتی اکانت را مجاهدین خلق بنام که در حال «تبلیغ و ستایش» مریم و مسعود رجوی، اشرف ۳، کانون‌های شورشی، طرح ۱۰ ماده‌ای، یا کمپین‌های سازمانی آن‌ها (#آری_به_جمهوری_دموکراتیک) باشد. اگر کاربر علیه رجوی و مجاهدین می‌نویسد، او مخالف مجاهدین است نه عضو آن‌ها!
   - احتمال خطر: ۹۵٪ الی ۱۰۰٪
۵. تجزیه‌طلب‌ها (جریان‌های قوم‌گرا، واگرا و ضد تمامیت ارضی ایران):
   - استفاده از هشتگ‌های شاخص یا ادبیات فدرالیسم و شوونیسم فارس: #کوردستان، #Rojhelat، #Kurdistan، #FreeKurdistan، #GüneyAzerbaycan، #آذربایجان_جنوبی، #SouthernAzerbaijan، #Ahwaz، #الاحواز، #Balochistan، #FreeBalochistan، #حق_تعیین_سرنوشت، #ملتها، #شوونیسم_فارس، #فدرالیسم، #ستم_ملی.
   - ترکیب شعار زن‌زندگی‌آزادی با ادبیات قومیتی و فدرالیسم.
   - احتمال فیک/سایبری/تفرقه‌افکن: ۷۵٪ الی ۹۵٪
۶. حساب رسمی دولتی / حاکمیتی خارجی و بین‌المللی (منحصراً دارای نشان تایید خاکستری / Grey Checkmark):
   - این دسته منحصراً متعلق به دولت‌ها، سران و نهادهای بین‌المللی خارجی (مانند کاخ سفید، سازمان ملل، وزارت خارجه آمریکا و کشورهای دموکراتیک) است که صراحتاً در بخش نشان رسمی بالا قید شده باشد: «🏛️ نشان رسمی خاکستری دولتی».
   - قانون طلایی و خط قرمز مطلق: اگر در مشخصات بالا تیک آبی (Blue Checkmark) یا عادی درج شده است، این اکانت مطلقاً تیک خاکستری ندارد و اکیداً نباید در این دسته قرار گیرد و هرگز نباید در متن پاسخت از عنوان «تیک خاکستری» یا «دسته ۶» استفاده کنی! تیک آبی هرگز به معنی تیک خاکستری نیست.
۷. نهاد رسمی دیپلماتیک یا دولتی خارجی (غیرایرانی): حساب‌های تاییدشده سفارتخانه‌ها یا وزارتخانه‌های خارجه سایر کشورهای جهان (مانند سفارت آمریکا، بریتانیا، آلمان، اسرائیل، فرانسه و...). سفارتخانه‌های جمهوری اسلامی ایران هرگز در این دسته نبوده و در دسته ۳-الف قرار دارند.
۸. روزنامه‌نگار مستقل یا رسانه معتبر: فقط خبرنگاران رسمی و بی‌طرف خبرگزاری‌های معتبر خبری (احتمال فیک: ۰٪).
   - هشدار بسیار مهم: فعالان سیاسی، فمینیست‌های رادیکال (مانند شادی صدر و فعالان مشابه)، مهره‌های سوپاپ اطمینان و انحراف قیام‌ها (مانند حسین رونقی @HosseinRonaghi)، چهره‌های چپ، و افرادی که گرایش‌های ضد پادشاهی دارند، حتی اگر وکیل، استاد دانشگاه، دکتری یا فعال حقوق بشر باشند، هرگز در این دسته قرار نمی‌گیرند و باید در دسته ۲ (چپ‌ها)، ۵ (تجزیه‌طلب‌ها) یا نفوذی‌ها طبقه‌بندی شوند!
۹. کاربر عادی / شهروند معمولی: زندگی روزمره و غیرسیاسی (احتمال فیک: ۵٪ الی ۱۵٪).

بر اساس اصول بالا، خروجی را دقیقاً در قالب ۴ قسمتی زیر بنویس:
🤖 تشخیص هویت اکانت:
📊 احتمال فیک/سایبری/بات بودن:
🚩 سرنخ‌ها و شواهد سازمانی یا رفتاری:
💡 حکم و هشدار امنیتی X-Ray:`;

  const cachedModelsList = Array.isArray(localData?.cachedModels)
    ? localData.cachedModels.filter(isSupportedChatModel)
    : [];

  let candidateModels = [
    modelToUse,
    ...cachedModelsList,
    DEFAULT_MODEL,
    'meta-llama/llama-4-scout-17b-16e-instruct',
    'meta-llama/llama-4-maverick-17b-128e-instruct',
    'qwen/qwen3-32b',
    'openai/gpt-oss-120b',
    'openai/gpt-oss-20b',
    'gemma2-9b-it',
    FALLBACK_MODEL
  ].filter((m, idx, arr) => m && arr.indexOf(m) === idx);

  let content = null;
  let activeModel = modelToUse;
  let lastErrorMessage = '';
  let hitRateLimit = false;
  let refreshedLiveModels = false;
  const triedModels = new Set();

  for (let i = 0; i < candidateModels.length && triedModels.size < 6; i++) {
    const candidate = candidateModels[i];
    if (!candidate || triedModels.has(candidate)) continue;
    triedModels.add(candidate);
    activeModel = candidate;

    const requestBody = {
      model: candidate,
      temperature: 0.3,
      max_tokens: 1400,
      messages: [
        { role: 'system', content: BOT_DETECTOR_SYSTEM_PROMPT },
        { role: 'user', content: userPrompt }
      ]
    };

    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 25000);

    try {
      const res = await fetch(GROQ_API_URL, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${apiKey}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(requestBody),
        signal: controller.signal
      });

      clearTimeout(timeoutId);

      if (res.ok) {
        const data = await res.json().catch(() => null);
        const rawMsgContent = data?.choices?.[0]?.message?.content || '';
        const cleanedContent = String(rawMsgContent)
          .replace(/<think>[\s\S]*?<\/think>/gi, '')
          .replace(/<think>[\s\S]*/gi, '')
          .trim();

        if (cleanedContent && cleanedContent.length >= 25) {
          content = cleanedContent;
          if (activeModel !== modelToUse) {
            chrome.storage.sync.set({ selectedModel: activeModel }).catch(() => {});
          }
          break;
        } else {
          console.warn(`[X-Ray SW] Model ${candidate} returned empty/incomplete content after stripping think tags. Trying next candidate...`);
        }
      } else {
        const errData = await res.json().catch(() => null);
        const msg = errData?.error?.message || `HTTP ${res.status}`;
        lastErrorMessage = msg;

        if (res.status === 401) {
          break;
        }

        // Dynamically query /v1/models if model does not exist / no access / decommissioned
        if (!refreshedLiveModels && (res.status === 404 || res.status === 400 || res.status === 403 || /does not exist|do not have access|decommissioned|not found/i.test(msg))) {
          refreshedLiveModels = true;
          const liveRes = await fetchAvailableModels(apiKey).catch(() => null);
          if (liveRes && liveRes.success && Array.isArray(liveRes.models) && liveRes.models.length > 0) {
            chrome.storage.local.set({ cachedModels: liveRes.models }).catch(() => {});
            const freshCandidates = liveRes.models.filter(m => !triedModels.has(m));
            candidateModels.splice(i + 1, 0, ...freshCandidates);
          }
        }

        if (res.status === 429 || msg.includes('Rate limit') || msg.includes('TPD')) {
          hitRateLimit = true;
          console.warn(`[X-Ray SW] Model ${candidate} reached rate limit (${msg}). Trying next candidate model...`);
        } else {
          console.warn(`[X-Ray SW] Model ${candidate} failed (${res.status}: ${msg}). Trying next candidate...`);
        }
      }
    } catch (err) {
      clearTimeout(timeoutId);
      lastErrorMessage = err.name === 'AbortError' ? 'پایان زمان بررسی (Timeout).' : `خطای شبکه: ${err.message}`;
      console.warn(`[X-Ray SW] Error with model ${candidate}:`, err);
    }
  }

  if (!content) {
    // Graceful Local Forensic Fallback so no account ever fails to be checked!
    const fallbackAlignment = evaluateAccountAlignment(enrichedAccountInfo, customMap, { allowFallback: true });
    if (fallbackAlignment) {
      const rep = fallbackAlignment.report || fallbackAlignment;
      const formattedAnalysis = `🤖 تشخیص هویت اکانت: ${rep.identity}
📊 احتمال فیک/سایبری/بات بودن: ${rep.probability}
🚩 سرنخ‌ها و شواهد سازمانی یا رفتاری:
${rep.redFlags}
💡 حکم و هشدار امنیتی X-Ray: ${rep.verdict}`;

      return finalizeAnalysisResult({
        success: true,
        analysis: formattedAnalysis,
        model: fallbackAlignment.model,
        isMekAlert: Boolean(fallbackAlignment.isMekAlert),
        isFalseFlag: Boolean(fallbackAlignment.isFalseFlag),
        harvestedData: enrichedAccountInfo.__harvestedData || null
      }, enrichedAccountInfo);
    }

    let friendlyMessage = lastErrorMessage;
    if (hitRateLimit) {
      friendlyMessage = `سقف مصرف روزانه توکن (Rate Limit) در Groq پر شده است.\n\nجزئیات خطای سرور:\n${lastErrorMessage}`;
    }
    return {
      success: false,
      error: hitRateLimit ? 'RATE_LIMIT' : 'API_ERROR',
      message: friendlyMessage || 'پاسخی از مدل دریافت نشد.'
    };
  }

  return finalizeAnalysisResult({
    success: true,
    analysis: content.trim(),
    model: activeModel,
    harvestedData: enrichedAccountInfo.__harvestedData || null
  }, enrichedAccountInfo);
}
